Object.assign(window.IND_FEED_BODY, {"g2-10-23":{"route":"#/gitav/10.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:23:en2","title":"Gita 10.23, in another translation","body":"And of the Rudras I am Sankara, of the Yakshas and Râkshasas the Lord of wealth (Kuvera), of the Vasus I am Pâvaka, and of mountains, Meru am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","23 of 42"]]},"gv-10-24":{"route":"#/gitav/10.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:24:en","title":"Bhagavad Gita 10.24","text":"पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम् ।\nसेनानीनामहं स्कन्दः सरसामस्मि सागरः ॥","lang":"sa","roman":"purodhasāṃ ca mukhyaṃ māṃ viddhi pārtha bṛhaspatim |\nsenānīnāmahaṃ skandaḥ sarasāmasmi sāgaraḥ ||","body":"And know Me, O Pârtha, of household priests the chief, Brihaspati: of generals I am Skanda; of lakes I am the ocean.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","24 of 42"]]},"g2-10-24":{"route":"#/gitav/10.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:24:en2","title":"Gita 10.24, in another translation","body":"And of priests, O son of Prithâ, know Me the chief, Brihaspati; of generals, I am Skanda; of bodies of water, I am the ocean.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","24 of 42"]]},"gv-10-25":{"route":"#/gitav/10.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:25:en","title":"Bhagavad Gita 10.25","text":"महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम् ।\nयज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः ॥","lang":"sa","roman":"maharṣīṇāṃ bhṛgurahaṃ girāmasmyekamakṣaram |\nyajñānāṃ japayajño’smi sthāvarāṇāṃ himālayaḥ ||","body":"Of the great Rishis Bhṛigu; of speech I am the one syllable; of sacrifices I am the sacrifice of silent repetitions; of immovable things the Himâlaya.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","25 of 42"]]},"g2-10-25":{"route":"#/gitav/10.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:25:en2","title":"Gita 10.25, in another translation","body":"Of the great Rishis I am Bhrigu; of words I am the one syllable \"Om\"; of Yajnas I am the Yajna of Japa (silent repetition); of immovable things the Himâlaya.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","25 of 42"]]},"gv-10-26":{"route":"#/gitav/10.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:26:en","title":"Bhagavad Gita 10.26","text":"अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः ।\nगन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः ॥","lang":"sa","roman":"aśvatthaḥ sarvavṛkṣāṇāṃ devarṣīṇāṃ ca nāradaḥ |\ngandharvāṇāṃ citrarathaḥ siddhānāṃ kapilo muniḥ ||","body":"Asvattha of all tree; and of divine Rishis Nârada; of Gandharvas Chitraratha; of the perfected the Muni Kapila.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","26 of 42"]]},"g2-10-26":{"route":"#/gitav/10.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:26:en2","title":"Gita 10.26, in another translation","body":"Of all trees (I am) the Ashvattha, and Nârada of Deva-Rishis; Chitraratha of Gandharvas am I, and the Muni Kapila of the perfected ones.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","26 of 42"]]},"gv-10-27":{"route":"#/gitav/10.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:27:en","title":"Bhagavad Gita 10.27","text":"उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम् ।\nऐरावतं गजेन्द्राणां नराणां च नराधिपम् ॥","lang":"sa","roman":"uccaiḥśravasamaśvānāṃ viddhi māmamṛtodbhavam |\nairāvataṃ gajendrāṇāṃ narāṇāṃ ca narādhipam ||","body":"Uchchaishravas of horses know me, nectar-born; Airâvata of lordly elephants, and of men the Monarch.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","27 of 42"]]},"g2-10-27":{"route":"#/gitav/10.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:27:en2","title":"Gita 10.27, in another translation","body":"Know Me among horses as Uchchaisshravas, Amrita-born; of lordly elephants Airâvata, and of men the king.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","27 of 42"]]},"gv-10-28":{"route":"#/gitav/10.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:28:en","title":"Bhagavad Gita 10.28","text":"आयुधानामहं वज्रं धेनूनामस्मि कामधुक् ।\nप्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः ॥","lang":"sa","roman":"āyudhānāmahaṃ vajraṃ dhenūnāmasmi kāmadhuk |\nprajanaścāsmi kandarpaḥ sarpāṇāmasmi vāsukiḥ ||","body":"Of weapons I am the thunderbolt; of cows I am Kâmadhuk; I am Kandarpa of the progenitors; of serpents Vâsuki am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","28 of 42"]]},"g2-10-28":{"route":"#/gitav/10.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:28:en2","title":"Gita 10.28, in another translation","body":"Of weapons I am the thunderbolt, of cows I am Kâmadhuk; I am the Kandarpa, the cause of offspring; of serpents I am Vâsuki.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","28 of 42"]]},"gv-10-29":{"route":"#/gitav/10.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:29:en","title":"Bhagavad Gita 10.29","text":"अनन्तश्चास्मि नागानां वरुणो यादसामहम् ।\nपितॄणामर्यमा चास्मि यमः संयमतामहम् ॥","lang":"sa","roman":"anantaścāsmi nāgānāṃ varuṇo yādasāmaham |\npitṝṇāmaryamā cāsmi yamaḥ saṃyamatāmaham ||","body":"And I am Ananta of Nâgas, Varuna of sea-dwellers I; and of ancestors Aryaman; Yama of governors am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","29 of 42"]]},"g2-10-29":{"route":"#/gitav/10.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:29:en2","title":"Gita 10.29, in another translation","body":"And Ananta of snakes I am, I am Varuna of water-beings; and Aryaman of Pitris I am, I am Yama of controllers.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","29 of 42"]]},"gv-10-30":{"route":"#/gitav/10.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:30:en","title":"Bhagavad Gita 10.30","text":"प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम् ।\nमृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम् ॥","lang":"sa","roman":"prahlādaścāsmi daityānāṃ kālaḥ kalayatāmaham |\nmṛgāṇāṃ ca mṛgendro’haṃ vainateyaśca pakṣiṇām ||","body":"And I am Prahlâda of Daityas; of calculators Time am I; and of wild beasts I the imperial beast; and Vainateya of birds.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","30 of 42"]]},"g2-10-30":{"route":"#/gitav/10.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:30:en2","title":"Gita 10.30, in another translation","body":"And Prahlâda am I of Diti's progeny, of measurers I am Time; and of beasts I am the lord of beasts, and Garuda of birds.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","30 of 42"]]},"gv-10-31":{"route":"#/gitav/10.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:31:en","title":"Bhagavad Gita 10.31","text":"पवनः पवतामस्मि रामः शस्त्रभृतामहम् ।\nझषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी ॥","lang":"sa","roman":"pavanaḥ pavatāmasmi rāmaḥ śastrabhṛtāmaham |\njhaṣāṇāṃ makaraścāsmi srotasāmasmi jāhnavī ||","body":"Of purifiers I am the wind; Rama of warriors I; and I am Makara of fishes; of streams the Gangâ am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","31 of 42"]]},"g2-10-31":{"route":"#/gitav/10.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:31:en2","title":"Gita 10.31, in another translation","body":"Of purifiers I am the wind, Râma of warriors am I; of fishes I am the shark, of streams I am Jâhnavi (the Ganges).","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","31 of 42"]]},"gv-10-32":{"route":"#/gitav/10.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:32:en","title":"Bhagavad Gita 10.32","text":"सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन ।\nअध्यात्मविद्या विद्यानां वादः प्रवदतामहम् ॥","lang":"sa","roman":"sargāṇāmādirantaśca madhyaṃ caivāhamarjuna |\nadhyātmavidyā vidyānāṃ vādaḥ pravadatāmaham ||","body":"Of creations the beginning and the ending, and also the middle am I, O Arjuna. Of sciences the science concerning the Self; the speech of orators I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","32 of 42"]]},"g2-10-32":{"route":"#/gitav/10.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:32:en2","title":"Gita 10.32, in another translation","body":"Of manifestations I, am the beginning, the middle and also the end; of all knowledges I am the knowledge of the Self, and Vâda of disputants.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","32 of 42"]]},"gv-10-33":{"route":"#/gitav/10.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:33:en","title":"Bhagavad Gita 10.33","text":"अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च ।\nअहमेवाक्षयः कालो धाताऽहं विश्वतोमुखः ॥","lang":"sa","roman":"akṣarāṇāmakāro’smi dvandvaḥ sāmāsikasya ca |\nahamevākṣayaḥ kālo dhātā’haṃ viśvatomukhaḥ ||","body":"Of letters the letter A I am, and the duality of a compound; I also everlasting Time; I the Supporter, whose face turns everywhere.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","33 of 42"]]},"g2-10-33":{"route":"#/gitav/10.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:33:en2","title":"Gita 10.33, in another translation","body":"Of letters the letter A am I, and Dvandva of all compounds; I alone am the inexhaustible Time, I the Sustainer (by dispensing fruits of actions) All-formed.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","33 of 42"]]},"gv-10-34":{"route":"#/gitav/10.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:34:en","title":"Bhagavad Gita 10.34","text":"मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम् ।\nकीर्तिः श्रीर्वाक्च नारीणां स्मृतिर्मेधा धृतिः क्षमा ॥","lang":"sa","roman":"mṛtyuḥ sarvaharaścāhamudbhavaśca bhaviṣyatām |\nkīrtiḥ śrīrvākca nārīṇāṃ smṛtirmedhā dhṛtiḥ kṣamā ||","body":"And all-devouring Death am I, and the origin of all to come; and of feminine qualities, fame, prosperity, speech, memory, intelligence, constancy, forgiveness.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","34 of 42"]]},"g2-10-34":{"route":"#/gitav/10.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:34:en2","title":"Gita 10.34, in another translation","body":"And I am the all-seizing Death, and the prosperity of those who are to be prosperous; of the feminine qualities (I am) Fame, Prosperity (or beauty), Inspiration, Memory, Intelligence, Constancy and Forbearance.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","34 of 42"]]},"gv-10-35":{"route":"#/gitav/10.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:35:en","title":"Bhagavad Gita 10.35","text":"बृहत्साम तथा साम्नां गायत्री छन्दसामहम् ।\nमासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः ॥","lang":"sa","roman":"bṛhatsāma tathā sāmnāṃ gāyatrī chandasāmaham |\nmāsānāṃ mārgaśīrṣo’hamṛtūnāṃ kusumākaraḥ ||","body":"Of hymns also Brihatsâman; Gâyatrî of metres am I; of months I am Mârgasîrsha; of seasons the flowery.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","35 of 42"]]},"g2-10-35":{"route":"#/gitav/10.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:35:en2","title":"Gita 10.35, in another translation","body":"Of Sâmas also I am the Brihat-Sâma, of metres Gâyatri am I; of months I am Mârgashirsha, of seasons the flowery season.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","35 of 42"]]},"gv-10-36":{"route":"#/gitav/10.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:36:en","title":"Bhagavad Gita 10.36","text":"द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम् ।\nजयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम् ॥","lang":"sa","roman":"dyūtaṃ chalayatāmasmi tejastejasvināmaham |\njayo’smi vyavasāyo’smi sattvaṃ sattvavatāmaham ||","body":"I am the gambling of the cheat, and the splendour of splendid things I; I am victory, I am determination, and the truth of the truthful I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","36 of 42"]]},"g2-10-36":{"route":"#/gitav/10.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:36:en2","title":"Gita 10.36, in another translation","body":"I am the gambling of the fraudulent, I am the power of the powerful; I am victory, I am effort, I am Sattva of the Sâttvika.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","36 of 42"]]},"gv-10-37":{"route":"#/gitav/10.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:37:en","title":"Bhagavad Gita 10.37","text":"वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनंजयः ।\nमुनीनामप्यहं व्यासः कवीनामुशना कविः ॥","lang":"sa","roman":"vṛṣṇīnāṃ vāsudevo’smi pāṇḍavānāṃ dhanaṃjayaḥ |\nmunīnāmapyahaṃ vyāsaḥ kavīnāmuśanā kaviḥ ||","body":"Of the Vṛishnis Vâsudeva am I; of the Pândavas Dhananjaya; of the Sages also I am Vyâsa; of poets Ushanâ the Bard.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","37 of 42"]]},"g2-10-37":{"route":"#/gitav/10.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:37:en2","title":"Gita 10.37, in another translation","body":"Of the Vrishnis I am Vâsudeva; of the Pândavas, Dhananjaya; and also of the Munis I am Vyâsa; of the sages, Ushanas the sage.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","37 of 42"]]},"gv-10-38":{"route":"#/gitav/10.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:38:en","title":"Bhagavad Gita 10.38","text":"दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम् ।\nमौनं चैवास्मि गुह्यानां ज्ञानं ज्ञानवतामहम् ॥","lang":"sa","roman":"daṇḍo damayatāmasmi nītirasmi jigīṣatām |\nmaunaṃ caivāsmi guhyānāṃ jñānaṃ jñānavatāmaham ||","body":"Of rulers I am the sceptre; of those that seek victory I am statesmanship; and of secrets I am also silence; the knowledge of knowers am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","38 of 42"]]},"g2-10-38":{"route":"#/gitav/10.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:38:en2","title":"Gita 10.38, in another translation","body":"Of punishers I am the sceptre; of those who seek to conquer, I am statesmanship; and also of things secret I am silence, and the knowledge of knowers am I.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","38 of 42"]]},"gv-10-39":{"route":"#/gitav/10.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:39:en","title":"Bhagavad Gita 10.39","text":"यच्चापि सर्वभूतानां बीजं तदहमर्जुन ।\nन तदस्ति विना यत्स्यान्मया भूतं चराचरम् ॥","lang":"sa","roman":"yaccāpi sarvabhūtānāṃ bījaṃ tadahamarjuna |\nna tadasti vinā yatsyānmayā bhūtaṃ carācaram ||","body":"And whatsoever is the seed of all beings, that am I, O Arjuna; nor is there aught, moving or unmoving, that may exist bereft of Me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","39 of 42"]]},"g2-10-39":{"route":"#/gitav/10.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:39:en2","title":"Gita 10.39, in another translation","body":"And whatsoever is the seed of all beings, that also am I, O Arjuna. There is no being, whether moving or unmoving, that can exist without Me.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","39 of 42"]]},"gv-10-40":{"route":"#/gitav/10.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:40:en","title":"Bhagavad Gita 10.40","text":"नान्तोऽस्ति मम दिव्यानां विभूतीनां परंतप ।\nएष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया ॥","lang":"sa","roman":"nānto’sti mama divyānāṃ vibhūtīnāṃ paraṃtapa |\neṣa tūddeśataḥ prokto vibhūtervistaro mayā ||","body":"There is no end of My divine powers, O Parantapa. What has been declared is illustrative of My infinite glory.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","40 of 42"]]},"g2-10-40":{"route":"#/gitav/10.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:40:en2","title":"Gita 10.40, in another translation","body":"There is no end of My divine attributes, O scorcher of foes; but this is a brief statement by Me of the particulars of My divine attributes.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","40 of 42"]]},"gv-10-41":{"route":"#/gitav/10.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:41:en","title":"Bhagavad Gita 10.41","text":"यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा ।\nतत्तदेवावगच्छ त्वं मम तेजोंऽशसंभवम् ॥","lang":"sa","roman":"yadyadvibhūtimatsattvaṃ śrīmadūrjitameva vā |\ntattadevāvagaccha tvaṃ mama tejoṃ’śasaṃbhavam ||","body":"Whatsoever is glorious, good, beautiful, and mighty, understand thou that to go forth from a fragment of My splendour.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","41 of 42"]]},"g2-10-41":{"route":"#/gitav/10.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:41:en2","title":"Gita 10.41, in another translation","body":"Whatever being there is great, prosperous or powerful, that know thou to be a product of a part of My splendour.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","41 of 42"]]},"gv-10-42":{"route":"#/gitav/10.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:42:en","title":"Bhagavad Gita 10.42","text":"अथवा बहुनैतेन किं ज्ञातेन तवार्जुन ।\nविष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत् ॥","lang":"sa","roman":"athavā bahunaitena kiṃ jñātena tavārjuna |\nviṣṭabhyāhamidaṃ kṛtsnamekāṃśena sthito jagat ||","body":"But what is the knowledge of all these details to thee, O Arjuna? Having pervaded this whole universe with one fragment of Myself, I remain.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","42 of 42"]]},"g2-10-42":{"route":"#/gitav/10.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 10 — The Glimpses of the Divine Glory","src":"gita:10:42:en2","title":"Gita 10.42, in another translation","body":"Or what avails thee to know all this diversity, O Arjuna? (Know thou this,. that) I exist, supporting this whole world by a portion of Myself.","facts":[["Chapter","The Glimpses of the Divine Glory"],["Verse","42 of 42"]]},"gv-11-1":{"route":"#/gitav/11.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:1:en","title":"Bhagavad Gita 11.1","text":"मदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम् ।\nयत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम ॥","lang":"sa","roman":"madanugrahāya paramaṃ guhyamadhyātmasaṃjñitam |\nyattvayoktaṃ vacastena moho’yaṃ vigato mama ||","body":"Arjuna said: This word of the supreme Secret concerning the Self, Thou hast spoken out of compassion; by this my delusion is taken away.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","1 of 55"]]},"g2-11-1":{"route":"#/gitav/11.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:1:en2","title":"Gita 11.1, in another translation","body":"By the supremely profound words, on the discrimination of Self, that have been spoken by Thee out of compassion towards me, this my delusion is gone.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","1 of 55"]]},"gv-11-2":{"route":"#/gitav/11.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:2:en","title":"Bhagavad Gita 11.2","text":"भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया ।\nत्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम् ॥","lang":"sa","roman":"bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā |\ntvattaḥ kamalapatrākṣa māhātmyamapi cāvyayam ||","body":"The production and destruction of beings have been heard by me in detail from Thee, O Lotus-eyed, and also Thy imperishable greatness.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","2 of 55"]]},"g2-11-2":{"route":"#/gitav/11.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:2:en2","title":"Gita 11.2, in another translation","body":"Of Thee, O lotus-eyed, I have heard at length, of the origin and dissolution of beings, as also Thy inexhaustible greatness.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","2 of 55"]]},"gv-11-3":{"route":"#/gitav/11.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:3:en","title":"Bhagavad Gita 11.3","text":"एवमेतद्यथात्थ त्वमात्मानं परमेश्वर ।\nद्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम ॥","lang":"sa","roman":"evametadyathāttha tvamātmānaṃ parameśvara |\ndraṣṭumicchāmi te rūpamaiśvaraṃ puruṣottama ||","body":"O supreme Lord, even as Thou describest Thyself, O best of beings, I desire to see Thy Form omnipotent.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","3 of 55"]]},"g2-11-3":{"route":"#/gitav/11.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:3:en2","title":"Gita 11.3, in another translation","body":"So it is, O Lord Supreme! as Thou hast declared Thyself. (Still) I desire to see Thy Ishvara-Form, O Purusha Supreme.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","3 of 55"]]},"gv-11-4":{"route":"#/gitav/11.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:4:en","title":"Bhagavad Gita 11.4","text":"मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो ।\nयोगेश्वर ततो मे त्वं दर्शयाऽत्मानमव्ययम् ॥","lang":"sa","roman":"manyase yadi tacchakyaṃ mayā draṣṭumiti prabho |\nyogeśvara tato me tvaṃ darśayā’tmānamavyayam ||","body":"If Thou thinkest that by me It can be seen, O Lord, Lord of Yoga, then show me Thine imperishable Self.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","4 of 55"]]},"g2-11-4":{"route":"#/gitav/11.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:4:en2","title":"Gita 11.4, in another translation","body":"If, O Lord, Thou thinkest me capable of seeing it, then, O Lord of Yogis, show me Thy immutable Self.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","4 of 55"]]},"gv-11-5":{"route":"#/gitav/11.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:5:en","title":"Bhagavad Gita 11.5","text":"पश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः ।\nनानाविधानि दिव्यानि नानावर्णाकृतीनि च ॥","lang":"sa","roman":"paśya me pārtha rūpāṇi śataśo’tha sahasraśaḥ |\nnānāvidhāni divyāni nānāvarṇākṛtīni ca ||","body":"The Blessed Lord said: Behold, O Pârtha, a Form of Me, a hundredfold, a thousandfold, various in kind, divine, various in colours and shapes.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","5 of 55"]]},"g2-11-5":{"route":"#/gitav/11.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:5:en2","title":"Gita 11.5, in another translation","body":"Behold, O son of Prithâ, by hundreds and thousands, My different forms celestial, of various colours and shapes.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","5 of 55"]]},"gv-11-6":{"route":"#/gitav/11.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:6:en","title":"Bhagavad Gita 11.6","text":"पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा ।\nबहून्यदृष्टपूर्वाणि पश्याऽश्चर्याणि भारत ॥","lang":"sa","roman":"paśyādityānvasūnrudrānaśvinau marutastathā |\nbahūnyadṛṣṭapūrvāṇi paśyā’ścaryāṇi bhārata ||","body":"Behold the Âdityas, the Vasus, the Rudras, the two Ashvins and also the Maruts; behold many marvels never seen ere this, O Bhârata.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","6 of 55"]]},"g2-11-6":{"route":"#/gitav/11.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:6:en2","title":"Gita 11.6, in another translation","body":"Behold the Adityas, the Vasus, the Rudras, the twin Ashvins, and the Maruts; behold, O descendant of Bharata, many wonders never seen before.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","6 of 55"]]},"gv-11-7":{"route":"#/gitav/11.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:7:en","title":"Bhagavad Gita 11.7","text":"इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम् ।\nमम देहे गुडाकेश यच्चान्यद्द्रष्टुमिच्छसि ॥","lang":"sa","roman":"ihaikasthaṃ jagatkṛtsnaṃ paśyādya sacarācaram |\nmama dehe guḍākeśa yaccānyaddraṣṭumicchasi ||","body":"Here, to-day, behold the whole universe, movable and immovable, standing in one in My body, O Gudâkesha, with aught else thou desirest to see.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","7 of 55"]]},"g2-11-7":{"route":"#/gitav/11.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:7:en2","title":"Gita 11.7, in another translation","body":"See now, O Gudâkesha, in this My body, the whole universe centred in one,—including the moving and the unmoving,—and all else that thou desirest to see.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","7 of 55"]]},"gv-11-8":{"route":"#/gitav/11.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:8:en","title":"Bhagavad Gita 11.8","text":"न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा ।\nदिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम् ॥","lang":"sa","roman":"na tu māṃ śakyase draṣṭumanenaiva svacakṣuṣā |\ndivyaṃ dadāmi te cakṣuḥ paśya me yogamaiśvaram ||","body":"But verily thou art not able to behold Me with these thine eyes; the divine eye I give unto thee. Behold My sovereign Yoga.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","8 of 55"]]},"g2-11-8":{"route":"#/gitav/11.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:8:en2","title":"Gita 11.8, in another translation","body":"But thou canst not see Me with these eyes of thine; I give thee supersensuous sight; behold My Yoga Power Supreme.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","8 of 55"]]},"gv-11-9":{"route":"#/gitav/11.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:9:en","title":"Bhagavad Gita 11.9","text":"एवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः ।\nदर्शयामास पार्थाय परमं रूपमैश्वरम् ॥","lang":"sa","roman":"evamuktvā tato rājanmahāyogeśvaro hariḥ |\ndarśayāmāsa pārthāya paramaṃ rūpamaiśvaram ||","body":"Sanjaya said: Having thus spoken, O King, the great Lord of Yoga, Hari, showed to Pârtha His supreme Form as Lord.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","9 of 55"]]},"g2-11-9":{"route":"#/gitav/11.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:9:en2","title":"Gita 11.9, in another translation","body":"Having thus spoken, O King, Hari, the Great Lord of Yoga, showed unto the son of Prithâ, His Supreme Ishvara-Form—","facts":[["Chapter","The Vision of the Universal Form"],["Verse","9 of 55"]]},"gv-11-10":{"route":"#/gitav/11.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:10:en","title":"Bhagavad Gita 11.10","text":"अनेकवक्त्रनयनमनेकाद्भुतदर्शनम् ।\nअनेकदिव्याभरणं दिव्यानेकोद्यतायुधम् ॥","lang":"sa","roman":"anekavaktranayanamanekādbhutadarśanam |\nanekadivyābharaṇaṃ divyānekodyatāyudham ||","body":"With many mouths and eyes, with many visions of marvel, with many divine ornaments, with many upraised divine weapons;","facts":[["Chapter","The Vision of the Universal Form"],["Verse","10 of 55"]]},"g2-11-10":{"route":"#/gitav/11.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:10:en2","title":"Gita 11.10, in another translation","body":"With numerous mouths and eyes, with numerous wondrous sights, with numerous celestial ornaments, with numerous celestial weapons uplifted;","facts":[["Chapter","The Vision of the Universal Form"],["Verse","10 of 55"]]},"gv-11-11":{"route":"#/gitav/11.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:11:en","title":"Bhagavad Gita 11.11","text":"दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम् ।\nसर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम् ॥","lang":"sa","roman":"divyamālyāmbaradharaṃ divyagandhānulepanam |\nsarvāścaryamayaṃ devamanantaṃ viśvatomukham ||","body":"Wearing divine necklaces and vestures, anointed with divine unguents, the God all-marvellous, boundless, with face turned everywhere.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","11 of 55"]]},"g2-11-11":{"route":"#/gitav/11.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:11:en2","title":"Gita 11.11, in another translation","body":"Wearing celestial garlands and apparel, anointed with celestial-scented unguents, the All-wonderful, Resplendent, Boundless and All-formed.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","11 of 55"]]},"gv-11-12":{"route":"#/gitav/11.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:12:en","title":"Bhagavad Gita 11.12","text":"दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता ।\nयदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः ॥","lang":"sa","roman":"divi sūryasahasrasya bhavedyugapadutthitā |\nyadi bhāḥ sadṛśī sā syādbhāsastasya mahātmanaḥ ||","body":"If the splendour of a thousand suns were to blaze out together in the sky, that might resemble the glory of that Mahâtman.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","12 of 55"]]},"g2-11-12":{"route":"#/gitav/11.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:12:en2","title":"Gita 11.12, in another translation","body":"If the splendour of a thousand suns were to rise up at once in the sky, that would be like the splendour of that Mighty Being.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","12 of 55"]]},"gv-11-13":{"route":"#/gitav/11.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:13:en","title":"Bhagavad Gita 11.13","text":"तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा ।\nअपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा ॥","lang":"sa","roman":"tatraikasthaṃ jagatkṛtsnaṃ pravibhaktamanekadhā |\napaśyaddevadevasya śarīre pāṇḍavastadā ||","body":"There Pândava beheld the whole universe, divided into manifold parts, standing in one in the body of the Deity of Deities.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","13 of 55"]]},"g2-11-13":{"route":"#/gitav/11.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:13:en2","title":"Gita 11.13, in another translation","body":"There in the body of the God of gods, the son of Pându then saw the whole universe resting in one, with its manifold divisions.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","13 of 55"]]},"gv-11-14":{"route":"#/gitav/11.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:14:en","title":"Bhagavad Gita 11.14","text":"ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः ।\nप्रणम्य शिरसा देवं कृताञ्जलिरभाषत ॥","lang":"sa","roman":"tataḥ sa vismayāviṣṭo hṛṣṭaromā dhanañjayaḥ |\npraṇamya śirasā devaṃ kṛtāñjalirabhāṣata ||","body":"Then he, Dhananjaya, overwhelmed with astonishment, his hair upstanding, bowed down his head to the Shining One, and with joined palms spake.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","14 of 55"]]},"g2-11-14":{"route":"#/gitav/11.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:14:en2","title":"Gita 11.14, in another translation","body":"Then Dhananjaya, filled with wonder, with his hair standing on end, bending down his head to the Deva in adoration, spoke with joined palms.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","14 of 55"]]},"gv-11-15":{"route":"#/gitav/11.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:15:en","title":"Bhagavad Gita 11.15","text":"पश्यामि देवांस्तव देव देहे ।\nसर्वांस्तथा भूतविशेषसङ्घान् ।\nब्रह्माणमीशं कमलासनस्थ ।\nमृषींश्च सर्वानुरगांश्च दिव्यान् ॥","lang":"sa","roman":"paśyāmi devāṃstava deva dehe |\nsarvāṃstathā bhūtaviśeṣasaṅghān |\nbrahmāṇamīśaṃ kamalāsanastha |\nmṛṣīṃśca sarvānuragāṃśca divyān ||","body":"Arjuna said: Within Thy Form, O God, the Gods I see, All grades of beings with distinctive marks; Brahma, the Lord, upon His lotus-throne, The Rishis all, and Serpents, the Divine.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","15 of 55"]]},"g2-11-15":{"route":"#/gitav/11.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:15:en2","title":"Gita 11.15, in another translation","body":"I see all the Devas, O Deva, in Thy body, and hosts of all grades of beings; Brahma, the Lord, seated on the lotus, and all the Rishis and celestial serpents.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","15 of 55"]]},"gv-11-16":{"route":"#/gitav/11.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:16:en","title":"Bhagavad Gita 11.16","text":"अनेकबाहूदरवक्त्रनेत्रं ।\nपश्यामि त्वां सर्वतोऽनन्तरूपम् ।\nनान्तं न मध्यं न पुनस्तवादिं ।\nपश्यामि विश्वेश्वर विश्वरूप ॥","lang":"sa","roman":"anekabāhūdaravaktranetraṃ |\npaśyāmi tvāṃ sarvato’nantarūpam |\nnāntaṃ na madhyaṃ na punastavādiṃ |\npaśyāmi viśveśvara viśvarūpa ||","body":"With mouths, eyes, arms, breasts multitudinous, I see Thee everywhere, unbounded Form. Beginning, middle, end, nor source of Thee, Infinite Lord, infinite Form, I find;","facts":[["Chapter","The Vision of the Universal Form"],["Verse","16 of 55"]]},"g2-11-16":{"route":"#/gitav/11.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:16:en2","title":"Gita 11.16, in another translation","body":"I see Thee of boundless form on every side with manifold arms, stomachs, mouths and eyes; neither the end nor the middle, nor also the beginning of Thee do I see, O Lord of the universe, O Universal Form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","16 of 55"]]},"gv-11-17":{"route":"#/gitav/11.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:17:en","title":"Bhagavad Gita 11.17","text":"किरीटिनं गदिनं चक्रिणं च ।\nतेजोराशिं सर्वतोदीप्तिमन्तम् ।\nपश्यामि त्वां दुर्निरीक्ष्यं समन्ता ।\nद्दीप्तानलार्कद्युतिमप्रमेयम् ॥","lang":"sa","roman":"kirīṭinaṃ gadinaṃ cakriṇaṃ ca |\ntejorāśiṃ sarvatodīptimantam |\npaśyāmi tvāṃ durnirīkṣyaṃ samantā |\nddīptānalārkadyutimaprameyam ||","body":"Shining, a mass of splendour everywhere, With discus, mace, tiara, I behold: Blazing as fire, as sun dazzling the gaze, From all sides in the sky, immeasurable.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","17 of 55"]]},"g2-11-17":{"route":"#/gitav/11.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:17:en2","title":"Gita 11.17, in another translation","body":"I see Thee with diadem, club, and discus; a mass of radiance shining everywhere, very hard to look at, all around blazing like burning fire and sun, and immeasurable.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","17 of 55"]]},"gv-11-18":{"route":"#/gitav/11.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:18:en","title":"Bhagavad Gita 11.18","text":"त्वमक्षरं परमं वेदितव्यं ।\nत्वमस्य विश्वस्य परं निधानम् ।\nत्वमव्ययः शाश्वतधर्मगोप्ता ।\nसनातनस्त्वं पुरुषो मतो मे ॥","lang":"sa","roman":"tvamakṣaraṃ paramaṃ veditavyaṃ |\ntvamasya viśvasya paraṃ nidhānam |\ntvamavyayaḥ śāśvatadharmagoptā |\nsanātanastvaṃ puruṣo mato me ||","body":"Lofty beyond all thought, unperishing, Thou treasure-house supreme, all-immanent; Eternal Dharma's changeless Guardian, Thou; As immemorial Man I think of Thee.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","18 of 55"]]},"g2-11-18":{"route":"#/gitav/11.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:18:en2","title":"Gita 11.18, in another translation","body":"Thou art the Imperishable, the Supreme Being, the one thing to be known. Thou art the great Refuge of this universe;. Thou art the undying Guardian of the Eternal Dharma, Thou art the Ancient. Purusha, I ween.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","18 of 55"]]},"gv-11-19":{"route":"#/gitav/11.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:19:en","title":"Bhagavad Gita 11.19","text":"अनादिमध्यान्तमनन्तवीर्य ।\nमनन्तबाहुं शशिसूर्यनेत्रम् ।\nपश्यामि त्वां दीप्तहुताशवक्त्रं ।\nस्वतेजसा विश्वमिदं तपन्तम् ॥","lang":"sa","roman":"anādimadhyāntamanantavīrya |\nmanantabāhuṃ śaśisūryanetram |\npaśyāmi tvāṃ dīptahutāśavaktraṃ |\nsvatejasā viśvamidaṃ tapantam ||","body":"Nor source, nor midst, nor end; infinite force, Unnumbered arms, the sun and moon Thine eyes I see Thy face, as sacrificial fire Blazing, its splendour burneth up the worlds.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","19 of 55"]]},"g2-11-19":{"route":"#/gitav/11.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:19:en2","title":"Gita 11.19, in another translation","body":"I see Thee without beginning, middle or end, infinite in power, of manifold arms; the sun and the moon Thine eyes, the burning fire Thy mouth; heating the whole universe with Thy radiance.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","19 of 55"]]},"gv-11-20":{"route":"#/gitav/11.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:20:en","title":"Bhagavad Gita 11.20","text":"द्यावापृथिव्योरिदमन्तरं हि ।\nव्याप्तं त्वयैकेन दिशश्च सर्वाः ।\nदृष्ट्वाऽद्भुतं रूपमुग्रं तवेदं ।\nलोकत्रयं प्रव्यथितं महात्मन् ॥","lang":"sa","roman":"dyāvāpṛthivyoridamantaraṃ hi |\nvyāptaṃ tvayaikena diśaśca sarvāḥ |\ndṛṣṭvā’dbhutaṃ rūpamugraṃ tavedaṃ |\nlokatrayaṃ pravyathitaṃ mahātman ||","body":"By Thee alone are filled the earth, the heavens, And all the regions that are stretched between; The triple worlds sink down, O mighty One, Before Thine awful manifested Form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","20 of 55"]]},"g2-11-20":{"route":"#/gitav/11.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:20:en2","title":"Gita 11.20, in another translation","body":"The space betwixt heaven and earth and all the quarters are filled by Thee alone; having seen this, Thy marvellous and awful Form, the three worlds are trembling with fear, O Great-souled One.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","20 of 55"]]},"gv-11-21":{"route":"#/gitav/11.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:21:en","title":"Bhagavad Gita 11.21","text":"अमी हि त्वां सुरसङ्घा विशन्ति ।\nकेचिद्भीताः प्राञ्जलयो गृणन्ति ।\nस्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः ।\nस्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः ॥","lang":"sa","roman":"amī hi tvāṃ surasaṅghā viśanti |\nkecidbhītāḥ prāñjalayo gṛṇanti |\nsvastītyuktvā maharṣisiddhasaṅghāḥ |\nstuvanti tvāṃ stutibhiḥ puṣkalābhiḥ ||","body":"To Thee the troops of Suras enter in, Some with joined palms in awe invoking Thee; Banded Maharshis, Siddhas, cry: \"All hail\"! Chanting Thy praises with resounding songs.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","21 of 55"]]},"g2-11-21":{"route":"#/gitav/11.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:21:en2","title":"Gita 11.21, in another translation","body":"Verily, into Thee enter these hosts of Devas; some extol Thee in fear with joined palms; \"May it be well!\" thus saying, bands of great Rishis and Siddhas praise Thee with splendid hymns.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","21 of 55"]]},"gv-11-22":{"route":"#/gitav/11.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:22:en","title":"Bhagavad Gita 11.22","text":"रुद्रादित्या वसवो ये च साध्या ।\nविश्वेऽश्विनौ मरुतश्चोष्मपाश्च ।\nगन्धर्वयक्षासुरसिद्धसङ्घा ।\nवीक्षन्ते त्वां विस्मिताश्चैव सर्वे ॥","lang":"sa","roman":"rudrādityā vasavo ye ca sādhyā |\nviśve’śvinau marutaścoṣmapāśca |\ngandharvayakṣāsurasiddhasaṅghā |\nvīkṣante tvāṃ vismitāścaiva sarve ||","body":"Rudras, Vasus, Sâdhyas and Adityas, Vishvas, the Ashvins, Maruts, Ushmapas, Gandharvas, Yakshas, Siddhas, Asuras, In wondering multitudes beholding Thee.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","22 of 55"]]},"g2-11-22":{"route":"#/gitav/11.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:22:en2","title":"Gita 11.22, in another translation","body":"The Rudras, Adityas, Vasus, Sâdhyas, Vishva-Devas, the two Ashvins, Maruts, Ushmapâs, and hosts of Gandharvas, Yakshas, Asuras, and Siddhas,—all these are looking at Thee, all quite astounded.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","22 of 55"]]},"gv-11-23":{"route":"#/gitav/11.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:23:en","title":"Bhagavad Gita 11.23","text":"रूपं महत्ते बहुवक्त्रनेत्रं ।\nमहाबाहो बहुबाहूरुपादम् ।\nबहूदरं बहुदंष्ट्राकरालं ।\nदृष्ट्वा लोकाः प्रव्यथितास्तथाऽहम् ॥","lang":"sa","roman":"rūpaṃ mahatte bahuvaktranetraṃ |\nmahābāho bahubāhūrupādam |\nbahūdaraṃ bahudaṃṣṭrākarālaṃ |\ndṛṣṭvā lokāḥ pravyathitāstathā’ham ||","body":"Thy mighty Form, with many mouths and eyes, Long armed, with thighs and feet innumerate, Vast-bosomed, set with many fearful teeth, The worlds see terror-struck, as also I.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","23 of 55"]]},"g2-11-23":{"route":"#/gitav/11.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:23:en2","title":"Gita 11.23, in another translation","body":"Having seen Thy immeasurable Form—with many mouths and eyes, O mighty-armed, with many arms, thighs and feet, with many stomachs, and fearful with many tusks,—the worlds are terrified, and so am I.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","23 of 55"]]},"gv-11-24":{"route":"#/gitav/11.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:24:en","title":"Bhagavad Gita 11.24","text":"नभःस्पृशं दीप्तमनेकवर्णं ।\nव्यात्ताननं दीप्तविशालनेत्रम् ।\nदृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा ।\nधृतिं न विन्दामि शमं च विष्णो ॥","lang":"sa","roman":"nabhaḥspṛśaṃ dīptamanekavarṇaṃ |\nvyāttānanaṃ dīptaviśālanetram |\ndṛṣṭvā hi tvāṃ pravyathitāntarātmā |\ndhṛtiṃ na vindāmi śamaṃ ca viṣṇo ||","body":"Radiant, Thou touchest heaven, rainbow-hued, With opened mouths and shining vast-orbed eyes. My inmost self is quaking, having seen, My strength is withered, Vishnu, and my peace.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","24 of 55"]]},"g2-11-24":{"route":"#/gitav/11.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:24:en2","title":"Gita 11.24, in another translation","body":"On seeing Thee touching the sky, shining in many a colour, with mouths wide open, with large fiery eyes, I am terrified at heart, and find no courage nor peace, O Vishnu.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","24 of 55"]]},"gv-11-25":{"route":"#/gitav/11.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:25:en","title":"Bhagavad Gita 11.25","text":"दंष्ट्राकरालानि च ते मुखानि ।\nदृष्ट्वैव कालानलसन्निभानि ।\nदिशो न जाने न लभे च शर्म ।\nप्रसीद देवेश जगन्निवास ॥","lang":"sa","roman":"daṃṣṭrākarālāni ca te mukhāni |\ndṛṣṭvaiva kālānalasannibhāni |\ndiśo na jāne na labhe ca śarma |\nprasīda deveśa jagannivāsa ||","body":"Like Time's destroying flames I see Thy teeth, Upstanding, spread within expanded jaws; Nought know I anywhere, no shelter find; Mercy, O God! re of all the worlds!","facts":[["Chapter","The Vision of the Universal Form"],["Verse","25 of 55"]]},"g2-11-25":{"route":"#/gitav/11.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:25:en2","title":"Gita 11.25, in another translation","body":"Having seen Thy mouths, fearful with tusks, (blazing) like Pralaya-fires, I know not the four quarters, nor do I find peace; have mercy, O Lord of the Devas, O Abode of the universe.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","25 of 55"]]},"gv-11-26":{"route":"#/gitav/11.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:26:en","title":"Bhagavad Gita 11.26","text":"अमी च त्वां धृतराष्ट्रस्य पुत्राः ।\nसर्वे सहैवावनिपालसङ्घैः ।\nभीष्मो द्रोणः सूतपुत्रस्तथाऽसौ ।\nसहास्मदीयैरपि योधमुख्यैः ॥","lang":"sa","roman":"amī ca tvāṃ dhṛtarāṣṭrasya putrāḥ |\nsarve sahaivāvanipālasaṅghaiḥ |\nbhīṣmo droṇaḥ sūtaputrastathā’sau |\nsahāsmadīyairapi yodhamukhyaiḥ ||","body":"The sons of Dhṛitarâshtra, and with them The multitude of all these kings of earth, Bhîshma, and Drona, Sûta's royal son, And all the noblest warriors of our hosts,","facts":[["Chapter","The Vision of the Universal Form"],["Verse","26 of 55"]]},"g2-11-26":{"route":"#/gitav/11.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:26:en2","title":"Gita 11.26, in another translation","body":"All these sons of Dhritarâshtra, with hosts of monarchs, Bhishma, Drona, and Sutaputra, with the warrior chiefs of ours, enter precipitately into Thy mouth, terrible with tusks and fearful to behold. Some are found sticking in the interstices of Thy teeth, with their heads crushed to powder.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","26 of 55"]]},"gv-11-27":{"route":"#/gitav/11.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:27:en","title":"Bhagavad Gita 11.27","text":"वक्त्राणि ते त्वरमाणा विशन्ति ।\nदंष्ट्राकरालानि भयानकानि ।\nकेचिद्विलग्ना दशनान्तरेषु ।\nसंदृश्यन्ते चूर्णितैरुत्तमाङ्गैः ॥","lang":"sa","roman":"vaktrāṇi te tvaramāṇā viśanti |\ndaṃṣṭrākarālāni bhayānakāni |\nkecidvilagnā daśanāntareṣu |\nsaṃdṛśyante cūrṇitairuttamāṅgaiḥ ||","body":"Into Thy gaping mouths they hurrying rush, Tremendous-toothed and terrible to see; Some caught within the gaps between Thy teeth Are seen, their heads to powder crushed and ground.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","27 of 55"]]},"gv-11-28":{"route":"#/gitav/11.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:28:en","title":"Bhagavad Gita 11.28","text":"यथा नदीनां बहवोऽम्बुवेगाः ।\nसमुद्रमेवाभिमुखा द्रवन्ति ।\nतथा तवामी नरलोकवीरा ।\nविशन्ति वक्त्राण्यभिविज्वलन्ति ॥","lang":"sa","roman":"yathā nadīnāṃ bahavo’mbuvegāḥ |\nsamudramevābhimukhā dravanti |\ntathā tavāmī naralokavīrā |\nviśanti vaktrāṇyabhivijvalanti ||","body":"As river-floods impetuously rush, Hurling their waters into ocean's lap, So fling themselves into Thy flaming mouths, In haste, these mighty men, these lords of earth.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","28 of 55"]]},"g2-11-28":{"route":"#/gitav/11.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:28:en2","title":"Gita 11.28, in another translation","body":"Verily, as the many torrents of rivers flow towards the ocean, so do these heroes in the world of men enter Thy fiercely flaming mouths.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","28 of 55"]]},"gv-11-29":{"route":"#/gitav/11.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:29:en","title":"Bhagavad Gita 11.29","text":"यथा प्रदीप्तं ज्वलनं पतङ्गा ।\nविशन्ति नाशाय समृद्धवेगाः ।\nतथैव नाशाय विशन्ति लोका ।\nस्तवापि वक्त्राणि समृद्धवेगाः ॥","lang":"sa","roman":"yathā pradīptaṃ jvalanaṃ pataṅgā |\nviśanti nāśāya samṛddhavegāḥ |\ntathaiva nāśāya viśanti lokā |\nstavāpi vaktrāṇi samṛddhavegāḥ ||","body":"As moths with quickened speed will headlong fly Into a flaming light, to fall destroyed, So also these, in haste precipitate, Enter within Thy mouths destroyed to fall.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","29 of 55"]]},"g2-11-29":{"route":"#/gitav/11.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:29:en2","title":"Gita 11.29, in another translation","body":"As moths precipitately rush into a blazing fire only to perish, even so do these creatures also precipitately rush into Thy mouths only to perish.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","29 of 55"]]},"gv-11-30":{"route":"#/gitav/11.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:30:en","title":"Bhagavad Gita 11.30","text":"लेलिह्यसे ग्रसमानः समन्ता ।\nल्लोकान्समग्रान्वदनैर्ज्वलद्भिः ।\nतेजोभिरापूर्य जगत्समग्रं ।\nभासस्तवोग्राः प्रतपन्ति विष्णो ॥","lang":"sa","roman":"lelihyase grasamānaḥ samantā |\nllokānsamagrānvadanairjvaladbhiḥ |\ntejobhirāpūrya jagatsamagraṃ |\nbhāsastavogrāḥ pratapanti viṣṇo ||","body":"On every side, all-swallowing, fiery-tongued, Thou lickest up mankind, devouring all; The glory filleth space: the universe Is burning, Vishnu, with Thy blazing rays.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","30 of 55"]]},"g2-11-30":{"route":"#/gitav/11.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:30:en2","title":"Gita 11.30, in another translation","body":"Swallowing all the worlds on every side with Thy flaming mouths, Thou are licking Thy lips. Thy fierce rays, filling the whole world with radiance, are burning, O Vishnu!","facts":[["Chapter","The Vision of the Universal Form"],["Verse","30 of 55"]]},"gv-11-31":{"route":"#/gitav/11.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:31:en","title":"Bhagavad Gita 11.31","text":"आख्याहि मे को भवानुग्ररूपो ।\nनमोऽस्तु ते देववर प्रसीद ।\nविज्ञातुमिच्छामि भवन्तमाद्यं ।\nन हि प्रजानामि तव प्रवृत्तिम् ॥","lang":"sa","roman":"ākhyāhi me ko bhavānugrarūpo |\nnamo’stu te devavara prasīda |\nvijñātumicchāmi bhavantamādyaṃ |\nna hi prajānāmi tava pravṛttim ||","body":"Reveal Thy Self; what awful Form art Thou? I worship Thee! Have mercy, God supreme! Thine inner Being I am fain to know; This Thy forth-streaming Life bewilders me.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","31 of 55"]]},"g2-11-31":{"route":"#/gitav/11.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:31:en2","title":"Gita 11.31, in another translation","body":"Tell me who Thou art, fierce in form. Salutation to Thee, O Deva Supreme; have mercy. I desire to know Thee, O Primeval One. I know not indeed Thy purpose.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","31 of 55"]]},"gv-11-32":{"route":"#/gitav/11.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:32:en","title":"Bhagavad Gita 11.32","text":"कालोऽस्मि लोकक्षयकृत्प्रवृद्धो ।\nलोकान्समाहर्तुमिह प्रवृत्तः ।\nऋतेऽपि त्वां न भविष्यन्ति सर्वे ।\nयेऽवस्थिताः प्रत्यनीकेषु योधाः ॥","lang":"sa","roman":"kālo’smi lokakṣayakṛtpravṛddho |\nlokānsamāhartumiha pravṛttaḥ |\nṛte’pi tvāṃ na bhaviṣyanti sarve |\nye’vasthitāḥ pratyanīkeṣu yodhāḥ ||","body":"Time am I, laying desolate the world, Made manifest on earth to slay mankind! Not one of all these warriors ranged for strife Escapeth death; thou shalt alone survive.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","32 of 55"]]},"g2-11-32":{"route":"#/gitav/11.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:32:en2","title":"Gita 11.32, in another translation","body":"I am the mighty world-destroying Time, here made manifest for the purpose of infolding the world. Even without thee, none of the warriors arrayed in the hostile armies shall live.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","32 of 55"]]},"gv-11-33":{"route":"#/gitav/11.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:33:en","title":"Bhagavad Gita 11.33","text":"तस्मात्त्वमुत्तिष्ठ यशो लभस्व ।\nजित्वा शत्रून् भुङ्क्ष्व राज्यं समृद्धम् ।\nमयैवैते निहताः पूर्वमेव ।\nनिमित्तमात्रं भव सव्यसाचिन् ॥","lang":"sa","roman":"tasmāttvamuttiṣṭha yaśo labhasva |\njitvā śatrūn bhuṅkṣva rājyaṃ samṛddham |\nmayaivaite nihatāḥ pūrvameva |\nnimittamātraṃ bhava savyasācin ||","body":"Therefore stand up! win for thyself renown, Conquer thy foes, enjoy the wealth filled realm, By Me they are already overcome, Be thou the outward cause, left-handed one.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","33 of 55"]]},"g2-11-33":{"route":"#/gitav/11.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:33:en2","title":"Gita 11.33, in another translation","body":"Therefore do thou arise and acquire fame. Conquer the enemies, and enjoy the unrivalled dominion. Verily by Myself have they been already slain; be thou merely an apparent cause, O Savyasâchin (Arjuna).","facts":[["Chapter","The Vision of the Universal Form"],["Verse","33 of 55"]]},"gv-11-34":{"route":"#/gitav/11.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:34:en","title":"Bhagavad Gita 11.34","text":"द्रोणं च भीष्मं च जयद्रथं च ।\nकर्णं तथाऽन्यानपि योधवीरान् ।\nमया हतांस्त्वं जहि मा व्यथिष्ठा ।\nयुध्यस्व जेतासि रणे सपत्नान् ॥","lang":"sa","roman":"droṇaṃ ca bhīṣmaṃ ca jayadrathaṃ ca |\nkarṇaṃ tathā’nyānapi yodhavīrān |\nmayā hatāṃstvaṃ jahi mā vyathiṣṭhā |\nyudhyasva jetāsi raṇe sapatnān ||","body":"Drona and Bhîshma and Jayadratha, Karna, and all the other warriors here, Are slain by Me. Destroy them fearlessly. Fight! thou shalt crush thy rivals in the field.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","34 of 55"]]},"g2-11-34":{"route":"#/gitav/11.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:34:en2","title":"Gita 11.34, in another translation","body":"Drona, Bhishma, Jayadratha, Karna, as well as other brave warriors,— these already killed by Me, do thou kill. Be not distressed with fear; fight, and thou shalt conquer thy enemies in battle.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","34 of 55"]]},"gv-11-35":{"route":"#/gitav/11.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:35:en","title":"Bhagavad Gita 11.35","text":"एतच्छ्रुत्वा वचनं केशवस्य ।\nकृताञ्जलिर्वेपमानः किरीटी ।\nनमस्कृत्वा भूय एवाह कृष्णं ।\nसगद्गदं भीतभीतः प्रणम्य ॥","lang":"sa","roman":"etacchrutvā vacanaṃ keśavasya |\nkṛtāñjalirvepamānaḥ kirīṭī |\nnamaskṛtvā bhūya evāha kṛṣṇaṃ |\nsagadgadaṃ bhītabhītaḥ praṇamya ||","body":"Sanjaya said: Having heard these words of Keshava, he who weareth a diadem, with joined palms, quaking and prostrating himself, spake again to Krishna, stammering with fear, casting down his face.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","35 of 55"]]},"g2-11-35":{"route":"#/gitav/11.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:35:en2","title":"Gita 11.35, in another translation","body":"Having, heard that speech of Keshava, the diademed one (Arjuna), with joined palms, trembling, prostrated himself, and again addressed Krishna in a choked voice, bowing down, overwhelmed with fear.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","35 of 55"]]},"gv-11-36":{"route":"#/gitav/11.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:36:en","title":"Bhagavad Gita 11.36","text":"स्थाने हृषीकेश तव प्रकीर्त्या ।\nजगत् प्रहृष्यत्यनुरज्यते च ।\nरक्षांसि भीतानि दिशो द्रवन्ति ।\nसर्वे नमस्यन्ति च सिद्धसङ्घाः ॥","lang":"sa","roman":"sthāne hṛṣīkeśa tava prakīrtyā |\njagat prahṛṣyatyanurajyate ca |\nrakṣāṃsi bhītāni diśo dravanti |\nsarve namasyanti ca siddhasaṅghāḥ ||","body":"Arjuna said: Hrishîkesha! in Thy magnificence Rightly the world rejoiceth, hymning Thee; The Râkshasas to every quarter fly In fear; the hosts of Siddhas prostrate fall.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","36 of 55"]]},"g2-11-36":{"route":"#/gitav/11.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:36:en2","title":"Gita 11.36, in another translation","body":"It is meet, O Hrishikesha, that the world is delighted and rejoices in Thy praise, that Râkshasas fly in fear to all quarters and all the hosts of Siddhas bow down to Thee in adoration.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","36 of 55"]]},"gv-11-37":{"route":"#/gitav/11.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:37:en","title":"Bhagavad Gita 11.37","text":"कस्माच्च ते न नमेरन्महात्मन् ।\nगरीयसे ब्रह्मणोऽप्यादिकर्त्रे ।\nअनन्त देवेश जगन्निवास ।\nत्वमक्षरं सदसत्तत्परं यत् ॥","lang":"sa","roman":"kasmācca te na nameranmahātman |\ngarīyase brahmaṇo’pyādikartre |\nananta deveśa jagannivāsa |\ntvamakṣaraṃ sadasattatparaṃ yat ||","body":"How should they otherwise, O loftiest Self! First Cause! Brahmâ Himself less great than Thou. Infinite, God of Gods, home of all worlds, Unperishing, Sat, Asat, That supreme!","facts":[["Chapter","The Vision of the Universal Form"],["Verse","37 of 55"]]},"g2-11-37":{"route":"#/gitav/11.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:37:en2","title":"Gita 11.37, in another translation","body":"And why should they not, O Great-souled One, bow to Thee, greater than, and the Primal Cause of even Brahmâ, O Infinite Being, O Lord of the Devas, O Abode of the universe? Thou art the Imperishable, the Being and the non-Being, (as well as) That which is Beyond (them).","facts":[["Chapter","The Vision of the Universal Form"],["Verse","37 of 55"]]},"gv-11-38":{"route":"#/gitav/11.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:38:en","title":"Bhagavad Gita 11.38","text":"त्वमादिदेवः पुरुषः पुराण ।\nस्त्वमस्य विश्वस्य परं निधानम् ।\nवेत्तासि वेद्यं च परं च धाम ।\nत्वया ततं विश्वमनन्तरूप ॥","lang":"sa","roman":"tvamādidevaḥ puruṣaḥ purāṇa |\nstvamasya viśvasya paraṃ nidhānam |\nvettāsi vedyaṃ ca paraṃ ca dhāma |\ntvayā tataṃ viśvamanantarūpa ||","body":"First of the Gods, most ancient Man Thou art. Supreme receptacle of all that lives; Knower and known, the dwelling-place on high; In Thy vast Form the universe is spread.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","38 of 55"]]},"g2-11-38":{"route":"#/gitav/11.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:38:en2","title":"Gita 11.38, in another translation","body":"Thou art the Primal Deva, the Ancient Purusha; Thou art the Supreme Refuge of this universe, Thou art the Knower, and the One Thing to be known; Thou art the Supreme Goal. By Thee is the universe pervaded, O Boundless Form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","38 of 55"]]},"gv-11-39":{"route":"#/gitav/11.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:39:en","title":"Bhagavad Gita 11.39","text":"वायुर्यमोऽग्निर्वरुणः शशाङ्कः ।\nप्रजापतिस्त्वं प्रपितामहश्च ।\nनमो नमस्तेऽस्तु सहस्रकृत्वः ।\nपुनश्च भूयोऽपि नमो नमस्ते ॥","lang":"sa","roman":"vāyuryamo’gnirvaruṇaḥ śaśāṅkaḥ |\nprajāpatistvaṃ prapitāmahaśca |\nnamo namaste’stu sahasrakṛtvaḥ |\npunaśca bhūyo’pi namo namaste ||","body":"Thou art Vâyu and Yama, Agni, moon, Varuna, Father, Grandsire of all; Hail, hail to Thee! a thousand times all hail! Hail unto Thee! again, again all hail!","facts":[["Chapter","The Vision of the Universal Form"],["Verse","39 of 55"]]},"g2-11-39":{"route":"#/gitav/11.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:39:en2","title":"Gita 11.39, in another translation","body":"Thou art Vâyu, Yama, Agni, Varuna, the Moon, Prajâpati, and the Great-Grandfather. Salutation, salutation to Thee, a thousand times, and again and again salutation, salutation to Thee!","facts":[["Chapter","The Vision of the Universal Form"],["Verse","39 of 55"]]},"gv-11-40":{"route":"#/gitav/11.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:40:en","title":"Bhagavad Gita 11.40","text":"नमः पुरस्तादथ पृष्ठतस्ते ।\nनमोऽस्तु ते सर्वत एव सर्व ।\nअनन्तवीर्यामितविक्रमस्त्वं ।\nसर्वं समाप्नोषि ततोऽसि सर्वः ॥","lang":"sa","roman":"namaḥ purastādatha pṛṣṭhataste |\nnamo’stu te sarvata eva sarva |\nanantavīryāmitavikramastvaṃ |\nsarvaṃ samāpnoṣi tato’si sarvaḥ ||","body":"Prostrate in front of Thee, prostrate behind; Prostrate on every side to Thee, O All. In power boundless, measureless in strength, Thou holdest all: then Thou Thyself art All.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","40 of 55"]]},"g2-11-40":{"route":"#/gitav/11.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:40:en2","title":"Gita 11.40, in another translation","body":"Salutation to Thee before and behind, salutation to Thee on every side, O All! Thou, infinite in power and infinite in prowess, pervadest all; wherefore Thou art All.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","40 of 55"]]},"gv-11-41":{"route":"#/gitav/11.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:41:en","title":"Bhagavad Gita 11.41","text":"सखेति मत्वा प्रसभं यदुक्तं ।\nहे कृष्ण हे यादव हे सखेति ।\nअजानता महिमानं तवेदं ।\nमया प्रमादात्प्रणयेन वापि ॥","lang":"sa","roman":"sakheti matvā prasabhaṃ yaduktaṃ |\nhe kṛṣṇa he yādava he sakheti |\najānatā mahimānaṃ tavedaṃ |\nmayā pramādātpraṇayena vāpi ||","body":"If, thinking Thee but friend, importunate, O Krishna! or O Yâdava! O friend! I cried, unknowing of Thy majesty, And careless in the fondness of my love;","facts":[["Chapter","The Vision of the Universal Form"],["Verse","41 of 55"]]},"g2-11-41":{"route":"#/gitav/11.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:41:en2","title":"Gita 11.41, in another translation","body":"Whatever I have presumptuously said from carelessness or love, addressing Thee as, \"O Krishna, O Yâdava, O friend,\" regarding Thee merely as a friend, unconscious of this Thy greatness—in whatever way I may have been disrespectful to Thee in fun, while walking, reposing, sitting, or at meals, when alone (with Thee), O Achyuta, or in company— [paragraph continues] I implore Thee, Immeasurable One, to forgive all this.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","41 of 55"]]},"gv-11-42":{"route":"#/gitav/11.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:42:en","title":"Bhagavad Gita 11.42","text":"यच्चावहासार्थमसत्कृतोऽसि ।\nविहारशय्यासनभोजनेषु ।\nएकोऽथवाप्यच्युत तत्समक्षं ।\nतत्क्षामये त्वामहमप्रमेयम् ॥","lang":"sa","roman":"yaccāvahāsārthamasatkṛto’si |\nvihāraśayyāsanabhojaneṣu |\neko’thavāpyacyuta tatsamakṣaṃ |\ntatkṣāmaye tvāmahamaprameyam ||","body":"If jesting I irreverence showed to Thee, At play, reposing, sitting or at meals, Alone, O sinless One, or with my friends, Forgive my error, O Thou boundless One.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","42 of 55"]]},"gv-11-43":{"route":"#/gitav/11.43","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:43:en","title":"Bhagavad Gita 11.43","text":"पितासि लोकस्य चराचरस्य ।\nत्वमस्य पूज्यश्च गुरुर्गरीयान् ।\nन त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो ।\nलोकत्रयेऽप्यप्रतिमप्रभाव ॥","lang":"sa","roman":"pitāsi lokasya carācarasya |\ntvamasya pūjyaśca gururgarīyān |\nna tvatsamo’styabhyadhikaḥ kuto’nyo |\nlokatraye’pyapratimaprabhāva ||","body":"Father of worlds, of all that moves and stands, Worthier of reverence than the Guru's self, There is none like to Thee. Who passeth Thee? Pre-eminent Thy power in all the worlds.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","43 of 55"]]},"g2-11-43":{"route":"#/gitav/11.43","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:43:en2","title":"Gita 11.43, in another translation","body":"Thou art the Father of the world, moving and unmoving; the object of its worship; greater than the great. None there exists who is equal to Thee in the three worlds; who then can excel Thee, O. Thou of power incomparable?","facts":[["Chapter","The Vision of the Universal Form"],["Verse","43 of 55"]]},"gv-11-44":{"route":"#/gitav/11.44","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:44:en","title":"Bhagavad Gita 11.44","text":"तस्मात्प्रणम्य प्रणिधाय कायं ।\nप्रसादये त्वामहमीशमीड्यम् ।\nपितेव पुत्रस्य सखेव सख्युः ।\nप्रियः प्रियायार्हसि देव सोढुम् ॥","lang":"sa","roman":"tasmātpraṇamya praṇidhāya kāyaṃ |\nprasādaye tvāmahamīśamīḍyam |\npiteva putrasya sakheva sakhyuḥ |\npriyaḥ priyāyārhasi deva soḍhum ||","body":"Therefore I fall before Thee; with my body I worship as it fitting; bless Thou me. As father with the son, as friend with friend, With the beloved as lover, bear with me.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","44 of 55"]]},"g2-11-44":{"route":"#/gitav/11.44","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:44:en2","title":"Gita 11.44, in another translation","body":"So prostrating my body in adoration, I crave Thy forgiveness, Lord adorable! As a father forgiveth his son, friend a dear friend, a beloved one his love, even so shouldst Thou forgive me, O Deva.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","44 of 55"]]},"gv-11-45":{"route":"#/gitav/11.45","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:45:en","title":"Bhagavad Gita 11.45","text":"अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा ।\nभयेन च प्रव्यथितं मनो मे ।\nतदेव मे दर्शय देव रूपं ।\nप्रसीद देवेश जगन्निवास ॥","lang":"sa","roman":"adṛṣṭapūrvaṃ hṛṣito’smi dṛṣṭvā |\nbhayena ca pravyathitaṃ mano me |\ntadeva me darśaya deva rūpaṃ |\nprasīda deveśa jagannivāsa ||","body":"I have seen that which none hath seen before, My heart is glad, yet faileth me for fear; Show me, O God, Thine other Form again— Mercy, O God of Gods, home of all worlds—","facts":[["Chapter","The Vision of the Universal Form"],["Verse","45 of 55"]]},"g2-11-45":{"route":"#/gitav/11.45","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:45:en2","title":"Gita 11.45, in another translation","body":"Overjoyed am I to have seen what I saw never before; yet my mind is distracted with terror. Show me, O Deva, only that Form of Thine. Have mercy, O Lord of Devas, O Abode of the universe.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","45 of 55"]]},"gv-11-46":{"route":"#/gitav/11.46","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:46:en","title":"Bhagavad Gita 11.46","text":"किरीटिनं गदिनं चक्रहस्त ।\nमिच्छामि त्वां द्रष्टुमहं तथैव ।\nतेनैव रूपेण चतुर्भुजेन ।\nसहस्रबाहो भव विश्वमूर्ते ॥","lang":"sa","roman":"kirīṭinaṃ gadinaṃ cakrahasta |\nmicchāmi tvāṃ draṣṭumahaṃ tathaiva |\ntenaiva rūpeṇa caturbhujena |\nsahasrabāho bhava viśvamūrte ||","body":"Diademed, mace and discus in Thy hand. Again I fain would see Thee as before; Put on again Thy four-armed shape, O Lord, O thousand-armed, of forms innumerate.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","46 of 55"]]},"g2-11-46":{"route":"#/gitav/11.46","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:46:en2","title":"Gita 11.46, in another translation","body":"Diademed, bearing a mace and a discus, Thee I desire to see as before. Assume that same four-armed Form, O Thou of thousand arms, of universal Form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","46 of 55"]]},"gv-11-47":{"route":"#/gitav/11.47","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:47:en","title":"Bhagavad Gita 11.47","text":"मया प्रसन्नेन तवार्जुनेदं ।\nरूपं परं दर्शितमात्मयोगात् ।\nतेजोमयं विश्वमनन्तमाद्यं ।\nयन्मे त्वदन्येन न दृष्टपूर्वम् ॥","lang":"sa","roman":"mayā prasannena tavārjunedaṃ |\nrūpaṃ paraṃ darśitamātmayogāt |\ntejomayaṃ viśvamanantamādyaṃ |\nyanme tvadanyena na dṛṣṭapūrvam ||","body":"The Blessed Lord said: Arjuna, by My favour thou hast seen, This loftiest Form by yoga's self revealed! Radiant, all-penetrating, endless, first, That none except thyself hath ever seen.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","47 of 55"]]},"g2-11-47":{"route":"#/gitav/11.47","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:47:en2","title":"Gita 11.47, in another translation","body":"Graciously have I shown to thee, O Arjuna, this Form supreme, by My own Yoga power, this resplendent, primeval, infinite, universal Form of Mine, which hath not been seen before by anyone else.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","47 of 55"]]},"gv-11-48":{"route":"#/gitav/11.48","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:48:en","title":"Bhagavad Gita 11.48","text":"न वेदयज्ञाध्ययनैर्न दानै ।\nर्न च क्रियाभिर्न तपोभिरुग्रैः ।\nएवंरूपः शक्य अहं नृलोके ।\nद्रष्टुं त्वदन्येन कुरुप्रवीर ॥","lang":"sa","roman":"na vedayajñādhyayanairna dānai |\nrna ca kriyābhirna tapobhirugraiḥ |\nevaṃrūpaḥ śakya ahaṃ nṛloke |\ndraṣṭuṃ tvadanyena kurupravīra ||","body":"Nor sacrifice, nor Vedas, alms, nor works, Nor sharp austerity, nor study deep, Can win the vision of this Form for man, Foremost of Kurus, thou alone hast seen.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","48 of 55"]]},"g2-11-48":{"route":"#/gitav/11.48","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:48:en2","title":"Gita 11.48, in another translation","body":"Neither by the study of the Veda and Yajna, nor by gifts, nor by rituals, nor by severe austerities, am I in such Form seen, in the world of men, by any other than thee, O great hero of the Kurus.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","48 of 55"]]},"gv-11-49":{"route":"#/gitav/11.49","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:49:en","title":"Bhagavad Gita 11.49","text":"मा ते व्यथा मा च विमूढभावो ।\nदृष्ट्वा रूपं घोरमीदृङ्ममेदम् ।\nव्यपेतभीः प्रीतमनाः पुनस्त्वं ।\nतदेव मे रूपमिदं प्रपश्य ॥","lang":"sa","roman":"mā te vyathā mā ca vimūḍhabhāvo |\ndṛṣṭvā rūpaṃ ghoramīdṛṅmamedam |\nvyapetabhīḥ prītamanāḥ punastvaṃ |\ntadeva me rūpamidaṃ prapaśya ||","body":"Be not bewildered, be thou not afraid, Because thou hast beheld this awful Form; Cast fear away, and let thy heart rejoice; Behold again Mine own familiar shape.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","49 of 55"]]},"g2-11-49":{"route":"#/gitav/11.49","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:49:en2","title":"Gita 11.49, in another translation","body":"Be not afraid nor bewildered, having beheld this Form of Mine, so terrific. With thy fears dispelled and with gladdened heart, now see again this (former) form of Mine.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","49 of 55"]]},"gv-11-50":{"route":"#/gitav/11.50","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:50:en","title":"Bhagavad Gita 11.50","text":"इत्यर्जुनं वासुदेवस्तथोक्त्वा ।\nस्वकं रूपं दर्शयामास भूयः ।\nआश्वासयामास च भीतमेनं ।\nभूत्वा पुनः सौम्यवपुर्महात्मा ॥","lang":"sa","roman":"ityarjunaṃ vāsudevastathoktvā |\nsvakaṃ rūpaṃ darśayāmāsa bhūyaḥ |\nāśvāsayāmāsa ca bhītamenaṃ |\nbhūtvā punaḥ saumyavapurmahātmā ||","body":"Sanjaya said: Vâsudeva, having thus spoken to Arjuna, again manifested His own Form, and consoled the terrified one, the Mahâtman again assuming a gentle form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","50 of 55"]]},"g2-11-50":{"route":"#/gitav/11.50","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:50:en2","title":"Gita 11.50, in another translation","body":"So Vâsudeva, having thus spoken to Arjuna, showed again His own Form and the Great-souled One, assuming His gentle Form, pacified him who was terrified.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","50 of 55"]]},"gv-11-51":{"route":"#/gitav/11.51","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:51:en","title":"Bhagavad Gita 11.51","text":"दृष्ट्वेदं मानुषं रूपं तवसौम्यं जनार्दन ।\nइदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः ॥","lang":"sa","roman":"dṛṣṭvedaṃ mānuṣaṃ rūpaṃ tavasaumyaṃ janārdana |\nidānīmasmi saṃvṛttaḥ sacetāḥ prakṛtiṃ gataḥ ||","body":"Arjuna said: Beholding again Thy gentle human Form, O Janârdana, I am now collected, and am restored to my own nature.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","51 of 55"]]},"g2-11-51":{"route":"#/gitav/11.51","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:51:en2","title":"Gita 11.51, in another translation","body":"Having seen this Thy gentle human Form, O Janârdana, my thoughts are now composed and I am restored to my nature.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","51 of 55"]]},"gv-11-52":{"route":"#/gitav/11.52","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:52:en","title":"Bhagavad Gita 11.52","text":"सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम ।\nदेवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः ॥","lang":"sa","roman":"sudurdarśamidaṃ rūpaṃ dṛṣṭavānasi yanmama |\ndevā apyasya rūpasya nityaṃ darśanakāṅkṣiṇaḥ ||","body":"The Blessed Lord said: This Form of Mine beholden by thee is very hard to see. Verily the Shining Ones ever long to behold this form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","52 of 55"]]},"g2-11-52":{"route":"#/gitav/11.52","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:52:en2","title":"Gita 11.52, in another translation","body":"Very hard indeed it is to see this Form of Mine which thou hast seen. Even the Devas ever long to behold this Form.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","52 of 55"]]},"gv-11-53":{"route":"#/gitav/11.53","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:53:en","title":"Bhagavad Gita 11.53","text":"नाहं वेदैर्न तपसा न दानेन न चेज्यया ।\nशक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा ॥","lang":"sa","roman":"nāhaṃ vedairna tapasā na dānena na cejyayā |\nśakya evaṃvidho draṣṭuṃ dṛṣṭavānasi māṃ yathā ||","body":"Nor can I be seen as thou hast seen Me by the Vedas, nor by austerities, nor by alms, or by offerings;","facts":[["Chapter","The Vision of the Universal Form"],["Verse","53 of 55"]]},"g2-11-53":{"route":"#/gitav/11.53","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:53:en2","title":"Gita 11.53, in another translation","body":"Neither by the Vedas, nor by austerity, nor by gifts, nor by sacrifice can I be seen as thou hast seen Me.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","53 of 55"]]},"gv-11-54":{"route":"#/gitav/11.54","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:54:en","title":"Bhagavad Gita 11.54","text":"भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन ।\nज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप ॥","lang":"sa","roman":"bhaktyā tvananyayā śakya ahamevaṃvidho’rjuna |\njñātuṃ draṣṭuṃ ca tattvena praveṣṭuṃ ca parantapa ||","body":"But by devotion to Me alone I may thus be perceived, Arjuna, and known and seen in essence, and entered, O Parantapa.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","54 of 55"]]},"g2-11-54":{"route":"#/gitav/11.54","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:54:en2","title":"Gita 11.54, in another translation","body":"But by the single-minded devotion I may in this Form, be known, O Arjuna, and seen in reality, and also entered into, O scorcher of foes.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","54 of 55"]]},"gv-11-55":{"route":"#/gitav/11.55","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:55:en","title":"Bhagavad Gita 11.55","text":"मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः ।\nनिर्वैरः सर्वभूतेषु यः स मामेति पाण्डव ॥","lang":"sa","roman":"matkarmakṛnmatparamo madbhaktaḥ saṅgavarjitaḥ |\nnirvairaḥ sarvabhūteṣu yaḥ sa māmeti pāṇḍava ||","body":"He who doeth actions for Me, whose supreme good I am, My devotee, freed from attachment without hatred of any being, he cometh unto Me, O Pândava.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","55 of 55"]]},"g2-11-55":{"route":"#/gitav/11.55","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 11 — The Vision of the Universal Form","src":"gita:11:55:en2","title":"Gita 11.55, in another translation","body":"He who does work for Me alone and has Me for his goal, is devoted to Me, is freed from attachment, and bears enmity towards no creature—he entereth into Me, O Pândava.","facts":[["Chapter","The Vision of the Universal Form"],["Verse","55 of 55"]]},"gv-12-1":{"route":"#/gitav/12.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:1:en","title":"Bhagavad Gita 12.1","text":"एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते ।\nयेचाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः ॥","lang":"sa","roman":"evaṃ satatayuktā ye bhaktāstvāṃ paryupāsate |\nyecāpyakṣaramavyaktaṃ teṣāṃ ke yogavittamāḥ ||","body":"Arjuna said: Those devotees who ever harmonised worship Thee, and those also who worship the Indestructible, the Unmanifested, whether of these is the more learned in yoga?","facts":[["Chapter","The Way of Devotion"],["Verse","1 of 20"]]},"g2-12-1":{"route":"#/gitav/12.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:1:en2","title":"Gita 12.1, in another translation","body":"Those devotees who, ever-steadfast, thus worship Thee, and those also who worship the Imperishable, the Unmanifested,—which of them are better versed in Yoga?","facts":[["Chapter","The Way of Devotion"],["Verse","1 of 20"]]},"gv-12-2":{"route":"#/gitav/12.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:2:en","title":"Bhagavad Gita 12.2","text":"मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते ।\nश्रद्धया परयोपेतास्ते मे युक्ततमा मताः ॥","lang":"sa","roman":"mayyāveśya mano ye māṃ nityayuktā upāsate |\nśraddhayā parayopetāste me yuktatamā matāḥ ||","body":"The Blessed Lord said: They who with mind fixed on Me ever harmonised worship Me, with faith supreme endowed, these, in My opinion, are best in yoga.","facts":[["Chapter","The Way of Devotion"],["Verse","2 of 20"]]},"g2-12-2":{"route":"#/gitav/12.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:2:en2","title":"Gita 12.2, in another translation","body":"Those who, fixing their mind on Me, worship Me, ever-steadfast, and endowed with supreme Shraddhâ, they in My opinion are the best versed in Yoga.","facts":[["Chapter","The Way of Devotion"],["Verse","2 of 20"]]},"gv-12-3":{"route":"#/gitav/12.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:3:en","title":"Bhagavad Gita 12.3","text":"ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते ।\nसर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम् ॥","lang":"sa","roman":"ye tvakṣaramanirdeśyamavyaktaṃ paryupāsate |\nsarvatragamacintyaṃ ca kūṭasthamacalaṃ dhruvam ||","body":"They who worship the Indestructible, the Ineffable, the unmanifested, Omnipresent, and Unthinkable, the Unchanging, Immutable, Eternal,","facts":[["Chapter","The Way of Devotion"],["Verse","3 of 20"]]},"g2-12-3":{"route":"#/gitav/12.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:3:en2","title":"Gita 12.3, in another translation","body":"But those also, who worship the Imperishable, the Indefinable, the Unmanifested, the Omnipresent, the Unthinkable, the Unchangeable, the Immovable, the Eternal,—having subdued all the senses, even-minded everywhere, engaged in the welfare of all beings, verily, they reach only Myself.","facts":[["Chapter","The Way of Devotion"],["Verse","3 of 20"]]},"gv-12-4":{"route":"#/gitav/12.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:4:en","title":"Bhagavad Gita 12.4","text":"संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः ।\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः ॥","lang":"sa","roman":"saṃniyamyendriyagrāmaṃ sarvatra samabuddhayaḥ |\nte prāpnuvanti māmeva sarvabhūtahite ratāḥ ||","body":"Restraining and subduing the senses, regarding everything equally, in the welfare of all rejoicing, these also come unto Me.","facts":[["Chapter","The Way of Devotion"],["Verse","4 of 20"]]},"gv-12-5":{"route":"#/gitav/12.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:5:en","title":"Bhagavad Gita 12.5","text":"क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम् ।\nअव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते ॥","lang":"sa","roman":"kleśo’dhikatarasteṣāmavyaktāsaktacetasām |\navyaktā hi gatirduḥkhaṃ dehavadbhiravāpyate ||","body":"The difficulty of those whose minds are set on the Unmanifested is greater; for the path of the Unmanifested is hard for the embodied to reach.","facts":[["Chapter","The Way of Devotion"],["Verse","5 of 20"]]},"g2-12-5":{"route":"#/gitav/12.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:5:en2","title":"Gita 12.5, in another translation","body":"Greater is their trouble whose minds are set on the Unmanifested; for the goal of the Unmanifested is very hard for the embodied to reach.","facts":[["Chapter","The Way of Devotion"],["Verse","5 of 20"]]},"gv-12-6":{"route":"#/gitav/12.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:6:en","title":"Bhagavad Gita 12.6","text":"ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः ।\nअनन्येनैव योगेन मां ध्यायन्त उपासते ॥","lang":"sa","roman":"ye tu sarvāṇi karmāṇi mayi saṃnyasya matparāḥ |\nananyenaiva yogena māṃ dhyāyanta upāsate ||","body":"Those verily who, renouncing all actions in Me and intent on Me, worship meditating on Me, with whole-hearted yoga,","facts":[["Chapter","The Way of Devotion"],["Verse","6 of 20"]]},"g2-12-6":{"route":"#/gitav/12.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:6:en2","title":"Gita 12.6, in another translation","body":"But those who worship Me, resigning all actions in Me, regarding Me as the Supreme Goal, meditating on Me with single-minded Yoga,—to these whose mind is set on Me, verily, I become ere long, O son of Prithâ, the Saviour out of the ocean of the mortal Samsâra.","facts":[["Chapter","The Way of Devotion"],["Verse","6 of 20"]]},"gv-12-7":{"route":"#/gitav/12.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:7:en","title":"Bhagavad Gita 12.7","text":"तेषामहं समुद्धर्ता मृत्युसंसारसागरात् ।\nभवामि नचिरात्पार्थ मय्यावेशितचेतसाम् ॥","lang":"sa","roman":"teṣāmahaṃ samuddhartā mṛtyusaṃsārasāgarāt |\nbhavāmi nacirātpārtha mayyāveśitacetasām ||","body":"These I speedily lift up from the ocean of death and existence, O Pârtha, their minds being fixed on Me.","facts":[["Chapter","The Way of Devotion"],["Verse","7 of 20"]]},"gv-12-8":{"route":"#/gitav/12.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:8:en","title":"Bhagavad Gita 12.8","text":"मय्येव मन आधत्स्व मयि बुद्धिं निवेशय ।\nनिवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः ॥","lang":"sa","roman":"mayyeva mana ādhatsva mayi buddhiṃ niveśaya |\nnivasiṣyasi mayyeva ata ūrdhvaṃ na saṃśayaḥ ||","body":"Place thy mind in me, into Me let thy Reason enter; then without doubt thou shalt abide in Me hereafter.","facts":[["Chapter","The Way of Devotion"],["Verse","8 of 20"]]},"g2-12-8":{"route":"#/gitav/12.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:8:en2","title":"Gita 12.8, in another translation","body":"Fix thy mind on Me only, place thy intellect in Me: (then) thou shalt no doubt live in Me hereafter.","facts":[["Chapter","The Way of Devotion"],["Verse","8 of 20"]]},"gv-12-9":{"route":"#/gitav/12.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:9:en","title":"Bhagavad Gita 12.9","text":"अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम् ।\nअभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय ॥","lang":"sa","roman":"atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram |\nabhyāsayogena tato māmicchāptuṃ dhanañjaya ||","body":"And if thou art not able firmly to fix thy mind on Me, then by the yoga of practice seek to reach Me, O Dhananjaya.","facts":[["Chapter","The Way of Devotion"],["Verse","9 of 20"]]},"g2-12-9":{"route":"#/gitav/12.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:9:en2","title":"Gita 12.9, in another translation","body":"If thou art unable to fix thy mind steadily on Me, then by Abhyâsa-Yoga do thou seek to reach Me, O Dhananjaya.","facts":[["Chapter","The Way of Devotion"],["Verse","9 of 20"]]},"gv-12-10":{"route":"#/gitav/12.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:10:en","title":"Bhagavad Gita 12.10","text":"अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव ।\nमदर्थमपि कर्माणि कुर्वन् सिद्धिमवाप्स्यसि ॥","lang":"sa","roman":"abhyāse’pyasamartho’si matkarmaparamo bhava |\nmadarthamapi karmāṇi kurvan siddhimavāpsyasi ||","body":"If also thou art not equal to constant practice, be intent on My service; performing actions for My sake, thou shalt attain perfection.","facts":[["Chapter","The Way of Devotion"],["Verse","10 of 20"]]},"g2-12-10":{"route":"#/gitav/12.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:10:en2","title":"Gita 12.10, in another translation","body":"If also thou art unable to practise Abhyâsa, be thou intent on doing actions -for My sake. Even by doing actions for My sake, thou shalt attain perfection.","facts":[["Chapter","The Way of Devotion"],["Verse","10 of 20"]]},"gv-12-11":{"route":"#/gitav/12.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:11:en","title":"Bhagavad Gita 12.11","text":"अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः ।\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान् ॥","lang":"sa","roman":"athaitadapyaśakto’si kartuṃ madyogamāśritaḥ |\nsarvakarmaphalatyāgaṃ tataḥ kuru yatātmavān ||","body":"If even to do this thou hast not strength, then, taking refuge in union with Me, renounce all fruit of action with the self controlled.","facts":[["Chapter","The Way of Devotion"],["Verse","11 of 20"]]},"g2-12-11":{"route":"#/gitav/12.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:11:en2","title":"Gita 12.11, in another translation","body":"If thou art unable to do even this, then taking refuge in Me, abandon the fruit of all action, self-controlled.","facts":[["Chapter","The Way of Devotion"],["Verse","11 of 20"]]},"gv-12-12":{"route":"#/gitav/12.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:12:en","title":"Bhagavad Gita 12.12","text":"श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते ।\nध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम् ॥","lang":"sa","roman":"śreyo hi jñānamabhyāsājjñānāddhyānaṃ viśiṣyate |\ndhyānātkarmaphalatyāgastyāgācchāntiranantaram ||","body":"Better indeed is wisdom than constant-practice; than wisdom, meditation is better; than meditation, renunciation of the fruit of action; on renunciation follows peace.","facts":[["Chapter","The Way of Devotion"],["Verse","12 of 20"]]},"g2-12-12":{"route":"#/gitav/12.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:12:en2","title":"Gita 12.12, in another translation","body":"Better indeed is knowledge than (blind) Abhyâsa; meditation (with knowledge) is more esteemed than (mere) knowledge; than meditation the renunciation of the fruit of action; peace immediately follows renunciation.","facts":[["Chapter","The Way of Devotion"],["Verse","12 of 20"]]},"gv-12-13":{"route":"#/gitav/12.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:13:en","title":"Bhagavad Gita 12.13","text":"अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च ।\nनिर्ममो निरहङ्कारः समदुःखसुखः क्षमी ॥","lang":"sa","roman":"adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca |\nnirmamo nirahaṅkāraḥ samaduḥkhasukhaḥ kṣamī ||","body":"He who beareth no ill-will to any being, friendly and compassionate, without attachment and egoism, balanced in pleasure and pain, and forgiving,","facts":[["Chapter","The Way of Devotion"],["Verse","13 of 20"]]},"g2-12-13":{"route":"#/gitav/12.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:13:en2","title":"Gita 12.13, in another translation","body":"He who hates no creature, and is friendly and compassionate towards all, who is free from the feelings of 'I and mine,' even-minded in pain and pleasure, forbearing, ever content, steady in meditation, self-controlled, and possessed of firm conviction, with mind and intellect fixed on Me,—he who is thus devoted to Me, is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","13 of 20"]]},"gv-12-14":{"route":"#/gitav/12.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:14:en","title":"Bhagavad Gita 12.14","text":"सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः ।\nमय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः ॥","lang":"sa","roman":"santuṣṭaḥ satataṃ yogī yatātmā dṛḍhaniścayaḥ |\nmayyarpitamanobuddhiryo madbhaktaḥ sa me priyaḥ ||","body":"Ever content, harmonious, with the self-controlled, resolute, with mind and Reason dedicated to Me, he, My devotee, is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","14 of 20"]]},"gv-12-15":{"route":"#/gitav/12.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:15:en","title":"Bhagavad Gita 12.15","text":"यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः ।\nहर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः ॥","lang":"sa","roman":"yasmānnodvijate loko lokānnodvijate ca yaḥ |\nharṣāmarṣabhayodvegairmukto yaḥ sa ca me priyaḥ ||","body":"He from whom the world doth not shrink away, who doth not shrink away from the world, freed from the anxieties of joy, anger, and fear, he is dear to me.","facts":[["Chapter","The Way of Devotion"],["Verse","15 of 20"]]},"g2-12-15":{"route":"#/gitav/12.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:15:en2","title":"Gita 12.15, in another translation","body":"He by whom the world is not agitated and who cannot be agitated by the world, who is freed from joy, envy, fear and anxiety,—he is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","15 of 20"]]},"gv-12-16":{"route":"#/gitav/12.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:16:en","title":"Bhagavad Gita 12.16","text":"अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः ।\nसर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः ॥","lang":"sa","roman":"anapekṣaḥ śucirdakṣa udāsīno gatavyathaḥ |\nsarvārambhaparityāgī yo madbhaktaḥ sa me priyaḥ ||","body":"He who wants nothing, is pure, expert, passionless, untroubled, renouncing every undertaking, he, My devotee, is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","16 of 20"]]},"g2-12-16":{"route":"#/gitav/12.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:16:en2","title":"Gita 12.16, in another translation","body":"He who is free from dependence, who is pure, prompt, unconcerned, untroubled, renouncing every undertaking,—he who is thus devoted to Me, is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","16 of 20"]]},"gv-12-17":{"route":"#/gitav/12.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:17:en","title":"Bhagavad Gita 12.17","text":"यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति ।\nशुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः ॥","lang":"sa","roman":"yo na hṛṣyati na dveṣṭi na śocati na kāṅkṣati |\nśubhāśubhaparityāgī bhaktimānyaḥ sa me priyaḥ ||","body":"He who neither loveth nor hateth, nor grieveth, nor desireth, renouncing good and evil, full of devotion, he is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","17 of 20"]]},"g2-12-17":{"route":"#/gitav/12.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:17:en2","title":"Gita 12.17, in another translation","body":"He who neither rejoices, nor hates, nor grieves, nor desires, renouncing good and evil, full of devotion, he is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","17 of 20"]]},"gv-12-18":{"route":"#/gitav/12.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:18:en","title":"Bhagavad Gita 12.18","text":"समः शत्रौ च मित्रे च तथा मानापमानयोः ।\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः ॥","lang":"sa","roman":"samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ |\nśītoṣṇasukhaduḥkheṣu samaḥ saṅgavivarjitaḥ ||","body":"Alike to foe and friend, and also in fame and ignominy, alike in cold and heat, pleasures and pains, destitute of attachment,","facts":[["Chapter","The Way of Devotion"],["Verse","18 of 20"]]},"g2-12-18":{"route":"#/gitav/12.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:18:en2","title":"Gita 12.18, in another translation","body":"He who is the same to friend and foe, and also in honour and dishonour; who is the same in heat and cold, and in pleasure and pain; who is free from attachment; to whom censure and praise are equal; who is silent, content with anything, homeless, steady-minded, full of devotion,—that man is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","18 of 20"]]},"gv-12-19":{"route":"#/gitav/12.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:19:en","title":"Bhagavad Gita 12.19","text":"तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येनकेनचित् ।\nअनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः ॥","lang":"sa","roman":"tulyanindāstutirmaunī santuṣṭo yenakenacit |\naniketaḥ sthiramatirbhaktimānme priyo naraḥ ||","body":"Taking equally praise and reproach, silent, wholly content with what cometh, homeless, firm in mind, full of devotion, that man is dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","19 of 20"]]},"gv-12-20":{"route":"#/gitav/12.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:20:en","title":"Bhagavad Gita 12.20","text":"ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते ।\nश्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः ॥","lang":"sa","roman":"ye tu dharmyāmṛtamidaṃ yathoktaṃ paryupāsate |\nśraddadhānā matparamā bhaktāste’tīva me priyāḥ ||","body":"They verily who partake of this life-giving wisdom as taught herein, endued with faith, I their supreme Object, devotees, they are surpassingly dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","20 of 20"]]},"g2-12-20":{"route":"#/gitav/12.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 12 — The Way of Devotion","src":"gita:12:20:en2","title":"Gita 12.20, in another translation","body":"And they who follow this Immortal Dharma, as described above, endued with Shraddhâ, regarding Me as the Supreme Goal, and devoted,—they are exceedingly dear to Me.","facts":[["Chapter","The Way of Devotion"],["Verse","20 of 20"]]},"gv-13-1":{"route":"#/gitav/13.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:1:en","title":"Bhagavad Gita 13.1","text":"इदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते ।\nएतद्यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः ॥","lang":"sa","roman":"idaṃ śarīraṃ kaunteya kṣetramityabhidhīyate |\netadyo vetti taṃ prāhuḥ kṣetrajña iti tadvidaḥ ||","body":"The Blessed Lord said: This body, son of Kuntî, is called the Field; that which knoweth it is called the Knower of the Field by the Sages.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","1 of 34"]]},"g2-13-1":{"route":"#/gitav/13.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:1:en2","title":"Gita 13.1, in another translation","body":"This body, O son of Kunti, is called Kshetra, and he who knows it is called Kshetrajna by those who know of them (Kshetra and Kshetrajna).","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","1 of 34"]]},"gv-13-2":{"route":"#/gitav/13.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:2:en","title":"Bhagavad Gita 13.2","text":"क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत ।\nक्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम ॥","lang":"sa","roman":"kṣetrajñaṃ cāpi māṃ viddhi sarvakṣetreṣu bhārata |\nkṣetrakṣetrajñayorjñānaṃ yattajjñānaṃ mataṃ mama ||","body":"Understand Me as the Knower of the Field in all Fields, O Bhârata. Wisdom as to the Field and the Knower of the Field, that in My opinion is the wisdom.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","2 of 34"]]},"g2-13-2":{"route":"#/gitav/13.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:2:en2","title":"Gita 13.2, in another translation","body":"Me do thou also know, O descendant of Bharata, to be Kshetrajna in all Kshetras. The knowledge of Kshetra and Kshetrajna is considered by Me to be the knowledge.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","2 of 34"]]},"gv-13-3":{"route":"#/gitav/13.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:3:en","title":"Bhagavad Gita 13.3","text":"तत्क्षेत्रं यच्च यादृक्च यद्विकारि यतश्च यत् ।\nस च यो यत्प्रभावश्च तत्समासेन मे शृणु ॥","lang":"sa","roman":"tatkṣetraṃ yacca yādṛkca yadvikāri yataśca yat |\nsa ca yo yatprabhāvaśca tatsamāsena me śṛṇu ||","body":"What that Field is and of what nature, how modified, and whence it is, and what He is and what His powers, hear that now briefly from Me.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","3 of 34"]]},"g2-13-3":{"route":"#/gitav/13.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:3:en2","title":"Gita 13.3, in another translation","body":"What the Kshetra is, what its properties are, what are its modifications, what effects arise from what causes, and also who He is and what His powers are, that hear from Me in brief.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","3 of 34"]]},"gv-13-4":{"route":"#/gitav/13.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:4:en","title":"Bhagavad Gita 13.4","text":"ऋषिभिर्बहुधा गीतं छन्दोभिर्विविधैः पृथक् ।\nब्रह्मसूत्रपदैश्चैव हेतुमद्भिर्विनिश्चितैः ॥","lang":"sa","roman":"ṛṣibhirbahudhā gītaṃ chandobhirvividhaiḥ pṛthak |\nbrahmasūtrapadaiścaiva hetumadbhirviniścitaiḥ ||","body":"Rishis have sung in manifold ways, in many various chants, and in decisive Brahma-sûtra verses full of reasonings.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","4 of 34"]]},"g2-13-4":{"route":"#/gitav/13.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:4:en2","title":"Gita 13.4, in another translation","body":"(This truth) has been sung by Rishis in many ways, in various distinctive chants, in passages indicative of Brahman, full of reasoning, and convincing.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","4 of 34"]]},"gv-13-5":{"route":"#/gitav/13.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:5:en","title":"Bhagavad Gita 13.5","text":"महाभूतान्यहङ्कारो बुद्धिरव्यक्तमेव च ।\nइन्द्रियाणि दशैकं च पञ्च चेन्द्रियगोचराः ॥","lang":"sa","roman":"mahābhūtānyahaṅkāro buddhiravyaktameva ca |\nindriyāṇi daśaikaṃ ca pañca cendriyagocarāḥ ||","body":"The great Elements, Individuality, Reason, and also the unmanifested, the ten senses and the one, and the five pastures of the senses;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","5 of 34"]]},"g2-13-5":{"route":"#/gitav/13.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:5:en2","title":"Gita 13.5, in another translation","body":"The great Elements, Egoism, Intellect, as also the Unmanifested (Mulâ Prakriti), the ten senses and the one (mind), and the five objects of the senses; desire, hatred, pleasure, pain, the, aggregate, intelligence, fortitude,—the Kshetra has been thus briefly described with its modifications.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","5 of 34"]]},"gv-13-6":{"route":"#/gitav/13.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:6:en","title":"Bhagavad Gita 13.6","text":"इच्छा द्वेषः सुखं दुःखं सङ्घातश्चेतनाधृतिः ।\nएतत्क्षेत्रं समासेन सविकारमुदाहृतम् ॥","lang":"sa","roman":"icchā dveṣaḥ sukhaṃ duḥkhaṃ saṅghātaścetanādhṛtiḥ |\netatkṣetraṃ samāsena savikāramudāhṛtam ||","body":"Desire, aversion, pleasure, pain, combination, intelligence, firmness; these, briefly described, constitute the Field and its modifications.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","6 of 34"]]},"gv-13-7":{"route":"#/gitav/13.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:7:en","title":"Bhagavad Gita 13.7","text":"अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम् ।\nआचार्योपासनं शौचं स्थैर्यमात्मविनिग्रहः ॥","lang":"sa","roman":"amānitvamadambhitvamahiṃsā kṣāntirārjavam |\nācāryopāsanaṃ śaucaṃ sthairyamātmavinigrahaḥ ||","body":"Humility, unpretentiousness, harmlessness, forgiveness, rectitude, service of the teacher, purity, steadfastness, self-control.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","7 of 34"]]},"g2-13-7":{"route":"#/gitav/13.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:7:en2","title":"Gita 13.7, in another translation","body":"Humility, unpretentiousness, non-injury, forbearance, uprightness, service to the teacher, purity, steadiness, self-control;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","7 of 34"]]},"gv-13-8":{"route":"#/gitav/13.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:8:en","title":"Bhagavad Gita 13.8","text":"इन्द्रियार्थेषु वैराग्यमनहङ्कार एव च ।\nजन्ममृत्युजराव्याधिदुःखदोषानुदर्शनम् ॥","lang":"sa","roman":"indriyārtheṣu vairāgyamanahaṅkāra eva ca |\njanmamṛtyujarāvyādhiduḥkhadoṣānudarśanam ||","body":"Dispassion towards the objects of the senses, and also absence of egoism, insight into the pain and evil of birth, death, old age and sickness,","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","8 of 34"]]},"g2-13-8":{"route":"#/gitav/13.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:8:en2","title":"Gita 13.8, in another translation","body":"The renunciation of sense-objects, and also absence of egoism; reflection on the evils of birth, death, old age, sickness and pain;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","8 of 34"]]},"gv-13-9":{"route":"#/gitav/13.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:9:en","title":"Bhagavad Gita 13.9","text":"असक्तिरनभिष्वङ्गः पुत्रदारगृहादिषु ।\nनित्यं च समचित्तत्वमिष्टानिष्टोपपत्तिषु ॥","lang":"sa","roman":"asaktiranabhiṣvaṅgaḥ putradāragṛhādiṣu |\nnityaṃ ca samacittatvamiṣṭāniṣṭopapattiṣu ||","body":"Unattachment, absence of self-identification with son, wife or home, and constant balance of mind in wished-for and unwished-for events,","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","9 of 34"]]},"g2-13-9":{"route":"#/gitav/13.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:9:en2","title":"Gita 13.9, in another translation","body":"Non-attachment, non-identification of self with son, wife, home, and the rest, and constant even-mindedness in the occurrence of the desirable and the un-undesirable;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","9 of 34"]]},"gv-13-10":{"route":"#/gitav/13.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:10:en","title":"Bhagavad Gita 13.10","text":"मयि चानन्ययोगेन भक्तिरव्यभिचारिणी ।\nविविक्तदेशसेवित्वमरतिर्जनसंसदि ॥","lang":"sa","roman":"mayi cānanyayogena bhaktiravyabhicāriṇī |\nviviktadeśasevitvamaratirjanasaṃsadi ||","body":"Unflinching devotion to Me by yoga, without other objects, resort to sequestered places, absence of enjoyment in the company of men,","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","10 of 34"]]},"g2-13-10":{"route":"#/gitav/13.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:10:en2","title":"Gita 13.10, in another translation","body":"Unswerving devotion to Me by the Yoga of non-separation, resort to sequestered places, distaste for the society of men;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","10 of 34"]]},"gv-13-11":{"route":"#/gitav/13.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:11:en","title":"Bhagavad Gita 13.11","text":"अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम् ।\nएतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोन्यथा ॥","lang":"sa","roman":"adhyātmajñānanityatvaṃ tattvajñānārthadarśanam |\netajjñānamiti proktamajñānaṃ yadatonyathā ||","body":"Constancy in the wisdom of the Self, understanding of the object of essential wisdom; that is declared to be the Wisdom; all against it is ignorance.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","11 of 34"]]},"g2-13-11":{"route":"#/gitav/13.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:11:en2","title":"Gita 13.11, in another translation","body":"Constant application to spiritual knowledge, understanding of the end of true knowledge: this is declared to be knowledge, and what is opposed to it is ignorance.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","11 of 34"]]},"gv-13-12":{"route":"#/gitav/13.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:12:en","title":"Bhagavad Gita 13.12","text":"ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वाऽमृतमश्नुते ।\nअनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते ॥","lang":"sa","roman":"jñeyaṃ yattatpravakṣyāmi yajjñātvā’mṛtamaśnute |\nanādimatparaṃ brahma na sattannāsaducyate ||","body":"I will declare that which ought to be known, that which being known immortality is enjoyed—the beginningless supreme Eternal, called neither being nor non-being.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","12 of 34"]]},"g2-13-12":{"route":"#/gitav/13.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:12:en2","title":"Gita 13.12, in another translation","body":"I shall describe that which has to be known, knowing which one attains to immortality, the beginningless Supreme Brahman. It is called neither being nor non-being.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","12 of 34"]]},"gv-13-13":{"route":"#/gitav/13.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:13:en","title":"Bhagavad Gita 13.13","text":"सर्वतः पाणिपादं तत्सर्वतोऽक्षिशिरोमुखम् ।\nसर्वतः श्रुतिमल्लोके सर्वमावृत्य तिष्ठति ॥","lang":"sa","roman":"sarvataḥ pāṇipādaṃ tatsarvato’kṣiśiromukham |\nsarvataḥ śrutimalloke sarvamāvṛtya tiṣṭhati ||","body":"Everywhere That hath hands and feet, everywhere eyes, heads, and mouths; all-hearing, He dwelleth in the world, enveloping all,","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","13 of 34"]]},"g2-13-13":{"route":"#/gitav/13.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:13:en2","title":"Gita 13.13, in another translation","body":"With hands and feet everywhere, with eyes, heads and mouths everywhere, with ears everywhere in the universe,—That exists pervading all.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","13 of 34"]]},"gv-13-14":{"route":"#/gitav/13.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:14:en","title":"Bhagavad Gita 13.14","text":"सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम् ।\nअसक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च ॥","lang":"sa","roman":"sarvendriyaguṇābhāsaṃ sarvendriyavivarjitam |\nasaktaṃ sarvabhṛccaiva nirguṇaṃ guṇabhoktṛ ca ||","body":"Shining with all sense-faculties without any senses; unattached supporting everything and free from qualities enjoying qualities;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","14 of 34"]]},"g2-13-14":{"route":"#/gitav/13.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:14:en2","title":"Gita 13.14, in another translation","body":"Shining by the functions of all the senses, yet without the senses; Absolute, yet sustaining all; devoid of Gunas, yet their experiencer.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","14 of 34"]]},"gv-13-15":{"route":"#/gitav/13.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:15:en","title":"Bhagavad Gita 13.15","text":"बहिरन्तश्च भूतानामचरं चरमेव च ।\nसूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत् ॥","lang":"sa","roman":"bahirantaśca bhūtānāmacaraṃ carameva ca |\nsūkṣmatvāttadavijñeyaṃ dūrasthaṃ cāntike ca tat ||","body":"Without and within all beings, immovable and also movable; by reason of His subtlety imperceptible; at hand and far away is That.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","15 of 34"]]},"g2-13-15":{"route":"#/gitav/13.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:15:en2","title":"Gita 13.15, in another translation","body":"Without and within (all) beings; the unmoving and also the moving; because of Its subtlety incomprehensible; It is far and near.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","15 of 34"]]},"gv-13-16":{"route":"#/gitav/13.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:16:en","title":"Bhagavad Gita 13.16","text":"अविभक्तं च भूतेषु विभक्तमिव च स्थितम् ।\nभूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च ॥","lang":"sa","roman":"avibhaktaṃ ca bhūteṣu vibhaktamiva ca sthitam |\nbhūtabhartṛ ca tajjñeyaṃ grasiṣṇu prabhaviṣṇu ca ||","body":"Not divided amid beings, and yet seated distributively; that is to be known as the supporter of beings; He devours and He generates.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","16 of 34"]]},"g2-13-16":{"route":"#/gitav/13.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:16:en2","title":"Gita 13.16, in another translation","body":"Impartible, yet It exists as if divided in beings: It is to be known as sustaining beings; and devouring, as well as generating (them).","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","16 of 34"]]},"gv-13-17":{"route":"#/gitav/13.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:17:en","title":"Bhagavad Gita 13.17","text":"ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते ।\nज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम् ॥","lang":"sa","roman":"jyotiṣāmapi tajjyotistamasaḥ paramucyate |\njñānaṃ jñeyaṃ jñānagamyaṃ hṛdi sarvasya viṣṭhitam ||","body":"That, the Light of all lights, is said to be beyond darkness; Wisdom, the Object of Wisdom, by Wisdom to be reached, seated in the hearts of all.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","17 of 34"]]},"g2-13-17":{"route":"#/gitav/13.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:17:en2","title":"Gita 13.17, in another translation","body":"The Light even of lights, It is said to be beyond darkness; Knowledge, and the One Thing to be known, the Goal of' knowledge, dwelling in the hearts of all.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","17 of 34"]]},"gv-13-18":{"route":"#/gitav/13.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:18:en","title":"Bhagavad Gita 13.18","text":"इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः ।\nमद्भक्त एतद्विज्ञाय मद्भावायोपपद्यते ॥","lang":"sa","roman":"iti kṣetraṃ tathā jñānaṃ jñeyaṃ coktaṃ samāsataḥ |\nmadbhakta etadvijñāya madbhāvāyopapadyate ||","body":"Thus the Field, Wisdom and the Object of Wisdom, have been briefly told. My devotee, thus knowing, enters into My Being.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","18 of 34"]]},"g2-13-18":{"route":"#/gitav/13.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:18:en2","title":"Gita 13.18, in another translation","body":"Thus Kshetra, knowledge, and that which has to be known, have been briefly stated. Knowing this, My devotee is fitted for My state.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","18 of 34"]]},"gv-13-19":{"route":"#/gitav/13.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:19:en","title":"Bhagavad Gita 13.19","text":"प्रकृतिं पुरुषं चैव विद्ध्यनादी उभावपि ।\nविकारांश्च गुणांश्चैव विद्धि प्रकृतिसंभवान् ॥","lang":"sa","roman":"prakṛtiṃ puruṣaṃ caiva viddhyanādī ubhāvapi |\nvikārāṃśca guṇāṃścaiva viddhi prakṛtisaṃbhavān ||","body":"Know thou that Matter and Spirit are both without beginning; and know thou also that modifications and qualities are all Matter-born.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","19 of 34"]]},"g2-13-19":{"route":"#/gitav/13.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:19:en2","title":"Gita 13.19, in another translation","body":"Know thou that Prakriti and Purusha are both beginningless; and know thou also that all modifications and Gunas are born of Prakriti.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","19 of 34"]]},"gv-13-20":{"route":"#/gitav/13.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:20:en","title":"Bhagavad Gita 13.20","text":"कार्यकारणकर्तृत्वे हेतुः प्रकृतिरुच्यते ।\nपुरुषः सुखदुःखानां भोक्तृत्वे हेतुरुच्यते ॥","lang":"sa","roman":"kāryakāraṇakartṛtve hetuḥ prakṛtirucyate |\npuruṣaḥ sukhaduḥkhānāṃ bhoktṛtve heturucyate ||","body":"Matter is called the cause of the generation of causes and effects; Spirit is called the cause of the enjoyment of pleasure and pain.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","20 of 34"]]},"g2-13-20":{"route":"#/gitav/13.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:20:en2","title":"Gita 13.20, in another translation","body":"In the production of the body and the senses, Prakriti is said to be the cause; in the experience of pleasure and pain, Purusha is said to be the cause.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","20 of 34"]]},"gv-13-21":{"route":"#/gitav/13.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:21:en","title":"Bhagavad Gita 13.21","text":"पुरुषः प्रकृतिस्थो हि भुङ्क्ते प्रकृतिजान्गुणान् ।\nकारणं गुणसङ्गोऽस्य सदसद्योनिजन्मसु ॥","lang":"sa","roman":"puruṣaḥ prakṛtistho hi bhuṅkte prakṛtijānguṇān |\nkāraṇaṃ guṇasaṅgo’sya sadasadyonijanmasu ||","body":"Spirit seated in Matter useth the qualities born of Matter; attachment to the qualities is the cause of his births in good and evil wombs.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","21 of 34"]]},"g2-13-21":{"route":"#/gitav/13.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:21:en2","title":"Gita 13.21, in another translation","body":"Purusha seated in Prakriti, experiences the Gunas born of Prakriti; the reason of his birth in good and evil wombs is his attachment to the Gunas.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","21 of 34"]]},"gv-13-22":{"route":"#/gitav/13.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:22:en","title":"Bhagavad Gita 13.22","text":"उपद्रष्टाऽनुमन्ता च भर्ता भोक्ता महेश्वरः ।\nपरमात्मेति चाप्युक्तो देहेऽस्मिन्पुरुषः परः ॥","lang":"sa","roman":"upadraṣṭā’numantā ca bhartā bhoktā maheśvaraḥ |\nparamātmeti cāpyukto dehe’sminpuruṣaḥ paraḥ ||","body":"Supervisor and permitter, supporter, enjoyer, the great Lord, and also the supreme Self; thus is styled in this body the supreme Spirit.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","22 of 34"]]},"g2-13-22":{"route":"#/gitav/13.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:22:en2","title":"Gita 13.22, in another translation","body":"And the Supreme Purusha in this body is also called the Looker-on, the Permitter, the Supporter, the Experiencer, the Great Lord, and the Highest Self.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","22 of 34"]]},"gv-13-23":{"route":"#/gitav/13.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:23:en","title":"Bhagavad Gita 13.23","text":"य एवं वेत्ति पुरुषं प्रकृतिं च गुणैःसह ।\nसर्वथा वर्तमानोऽपि न स भूयोऽभिजायते ॥","lang":"sa","roman":"ya evaṃ vetti puruṣaṃ prakṛtiṃ ca guṇaiḥsaha |\nsarvathā vartamāno’pi na sa bhūyo’bhijāyate ||","body":"He who thus knoweth Spirit and Matter with its qualities, in whatsoever condition he may be, he shall not be born again.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","23 of 34"]]},"g2-13-23":{"route":"#/gitav/13.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:23:en2","title":"Gita 13.23, in another translation","body":"He who thus knows the Purusha and Prakriti together with the Gunas, whatever his life, is not born again.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","23 of 34"]]},"gv-13-24":{"route":"#/gitav/13.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:24:en","title":"Bhagavad Gita 13.24","text":"ध्यानेनात्मनि पश्यन्ति केचिदात्मानमात्मना ।\nअन्ये सांख्येन योगेन कर्मयोगेन चापरे ॥","lang":"sa","roman":"dhyānenātmani paśyanti kecidātmānamātmanā |\nanye sāṃkhyena yogena karmayogena cāpare ||","body":"Some by meditation behold the Self in the self by the Self; others by the Sânkhya Yoga, and others by the Yoga of Action;","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","24 of 34"]]},"g2-13-24":{"route":"#/gitav/13.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:24:en2","title":"Gita 13.24, in another translation","body":"Some by meditation behold the Self in their own intelligence by the purified heart, others by the path of knowledge, others again by Karma Yoga.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","24 of 34"]]},"gv-13-25":{"route":"#/gitav/13.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:25:en","title":"Bhagavad Gita 13.25","text":"अन्ये त्वेवमजानन्तः श्रुत्वाऽन्येभ्य उपासते ।\nतेऽपि चातितरन्त्येव मृत्युं श्रुतिपरायणाः ॥","lang":"sa","roman":"anye tvevamajānantaḥ śrutvā’nyebhya upāsate |\nte’pi cātitarantyeva mṛtyuṃ śrutiparāyaṇāḥ ||","body":"Others also, ignorant of this, having heard of it from others, worship; and these also cross beyond death, adhering to what they had heard.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","25 of 34"]]},"g2-13-25":{"route":"#/gitav/13.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:25:en2","title":"Gita 13.25, in another translation","body":"Others again not knowing thus, worship as they have heard from others. [paragraph continues] Even these go beyond death, regarding what they have heard as the Supreme Refuge.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","25 of 34"]]},"gv-13-26":{"route":"#/gitav/13.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:26:en","title":"Bhagavad Gita 13.26","text":"यावत्सञ्जायते किञ्चित्सत्त्वं स्थावरजङ्गमम् ।\nक्षेत्रक्षेत्रज्ञसंयोगात्तद्विद्धि भरतर्षभ ॥","lang":"sa","roman":"yāvatsañjāyate kiñcitsattvaṃ sthāvarajaṅgamam |\nkṣetrakṣetrajñasaṃyogāttadviddhi bharatarṣabha ||","body":"Whatsoever creature is born immobile or mobile, know thou, O best of the Bhâratas, that it is from the union between the Field and the Knower of the Field.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","26 of 34"]]},"g2-13-26":{"route":"#/gitav/13.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:26:en2","title":"Gita 13.26, in another translation","body":"Whatever being is born, the moving or the unmoving, O bull of the Bhâratas, know it to be from the union of Kshetra and Kshetrajna.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","26 of 34"]]},"gv-13-27":{"route":"#/gitav/13.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:27:en","title":"Bhagavad Gita 13.27","text":"समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम् ।\nविनश्यत्स्वविनश्यन्तं यः पश्यति स पश्यति ॥","lang":"sa","roman":"samaṃ sarveṣu bhūteṣu tiṣṭhantaṃ parameśvaram |\nvinaśyatsvavinaśyantaṃ yaḥ paśyati sa paśyati ||","body":"Seated equally in all beings, the supreme Lord, unperishing within the perishing—he who thus seeth, he seeth.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","27 of 34"]]},"g2-13-27":{"route":"#/gitav/13.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:27:en2","title":"Gita 13.27, in another translation","body":"He sees, who sees the Lord Supreme, existing equally in all beings, deathless in the dying.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","27 of 34"]]},"gv-13-28":{"route":"#/gitav/13.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:28:en","title":"Bhagavad Gita 13.28","text":"समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम् ।\nन हिनस्त्यात्मनाऽऽत्मानं ततो याति परां गतिम् ॥","lang":"sa","roman":"samaṃ paśyanhi sarvatra samavasthitamīśvaram |\nna hinastyātmanā’’tmānaṃ tato yāti parāṃ gatim ||","body":"Seeing indeed everywhere the same Lord equally dwelling, he doth not destroy the Self, and thus treads the highest Path.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","28 of 34"]]},"g2-13-28":{"route":"#/gitav/13.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:28:en2","title":"Gita 13.28, in another translation","body":"Since seeing the Lord equally existent everywhere, he injures not Self by self, and so goes to the highest Goal.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","28 of 34"]]},"gv-13-29":{"route":"#/gitav/13.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:29:en","title":"Bhagavad Gita 13.29","text":"प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः ।\nयः पश्यति तथाऽऽत्मानमकर्तारं स पश्यति ॥","lang":"sa","roman":"prakṛtyaiva ca karmāṇi kriyamāṇāni sarvaśaḥ |\nyaḥ paśyati tathā’’tmānamakartāraṃ sa paśyati ||","body":"He who seeth that Matter verily performeth all actions, and that the Self is actionless, he seeth.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","29 of 34"]]},"g2-13-29":{"route":"#/gitav/13.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:29:en2","title":"Gita 13.29, in another translation","body":"He sees, who sees that all actions are done by Prakriti alone and that the Self is actionless.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","29 of 34"]]},"gv-13-30":{"route":"#/gitav/13.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:30:en","title":"Bhagavad Gita 13.30","text":"यदा भूतपृथग्भावमेकस्थमनुपश्यति ।\nतत एव च विस्तारं ब्रह्म सम्पद्यते तदा ॥","lang":"sa","roman":"yadā bhūtapṛthagbhāvamekasthamanupaśyati |\ntata eva ca vistāraṃ brahma sampadyate tadā ||","body":"When he perceiveth the diversified existence of beings as rooted in One, and spreading forth from it, then he reacheth the Eternal","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","30 of 34"]]},"g2-13-30":{"route":"#/gitav/13.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:30:en2","title":"Gita 13.30, in another translation","body":"When he sees the separate existence of all beings inherent in the One, and their expansion from That (One) alone, he then becomes Brahman.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","30 of 34"]]},"gv-13-31":{"route":"#/gitav/13.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:31:en","title":"Bhagavad Gita 13.31","text":"अनादित्वान्निर्गुणत्वात्परमात्मायमव्ययः ।\nशरीरस्थोऽपि कौन्तेय न करोति न लिप्यते ॥","lang":"sa","roman":"anāditvānnirguṇatvātparamātmāyamavyayaḥ |\nśarīrastho’pi kaunteya na karoti na lipyate ||","body":"Being beginningless and without qualities, the imperishable supreme Self, though seated in the body, O Kaunteya, worketh not nor is affected.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","31 of 34"]]},"g2-13-31":{"route":"#/gitav/13.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:31:en2","title":"Gita 13.31, in another translation","body":"Being without beginning and devoid of Gunas, this Supreme Self, immutable, O son of Kunti, though existing in the body neither acts nor is affected.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","31 of 34"]]},"gv-13-32":{"route":"#/gitav/13.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:32:en","title":"Bhagavad Gita 13.32","text":"यथा सर्वगतं सौक्ष्म्यादाकाशं नोपलिप्यते ।\nसर्वत्रावस्थितो देहे तथाऽऽत्मा नोपलिप्यते ॥","lang":"sa","roman":"yathā sarvagataṃ saukṣmyādākāśaṃ nopalipyate |\nsarvatrāvasthito dehe tathā’’tmā nopalipyate ||","body":"As the omnipresent ether is not affected, by reason of its subtlety, so seated everywhere in the body the Self is not affected.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","32 of 34"]]},"g2-13-32":{"route":"#/gitav/13.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:32:en2","title":"Gita 13.32, in another translation","body":"As the all-pervading Akâsha, because of its subtlety, is not tainted, so the Self existent in the body everywhere is not tainted.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","32 of 34"]]},"gv-13-33":{"route":"#/gitav/13.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:33:en","title":"Bhagavad Gita 13.33","text":"यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः ।\nक्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति भारत ॥","lang":"sa","roman":"yathā prakāśayatyekaḥ kṛtsnaṃ lokamimaṃ raviḥ |\nkṣetraṃ kṣetrī tathā kṛtsnaṃ prakāśayati bhārata ||","body":"As the one sun illumineth the whole earth, so the Lord of the Field illumineth the whole Field, O Bhârata.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","33 of 34"]]},"g2-13-33":{"route":"#/gitav/13.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:33:en2","title":"Gita 13.33, in another translation","body":"As the one sun illumines all this world, so does He who abides in the Kshetra, O descendant of Bharata, illumine the whole Kshetra.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","33 of 34"]]},"gv-13-34":{"route":"#/gitav/13.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:34:en","title":"Bhagavad Gita 13.34","text":"क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा ।\nभूतप्रकृतिमोक्षं च ये विदुर्यान्ति ते परम् ॥","lang":"sa","roman":"kṣetrakṣetrajñayorevamantaraṃ jñānacakṣuṣā |\nbhūtaprakṛtimokṣaṃ ca ye viduryānti te param ||","body":"They who by the eyes of Wisdom perceive this difference between the Field and the Knower of the Field, and the liberation of beings from Matter they go to the Supreme.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","34 of 34"]]},"g2-13-34":{"route":"#/gitav/13.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 13 — The Discrimination of the Kshetra and the Kshetrajna","src":"gita:13:34:en2","title":"Gita 13.34, in another translation","body":"They who thus with the eye of knowledge perceive the distinction between the Kshetra and the Kshetrajna, and also the emancipation from the Prakriti of beings, they go to the Supreme.","facts":[["Chapter","The Discrimination of the Kshetra and the Kshetrajna"],["Verse","34 of 34"]]},"gv-14-1":{"route":"#/gitav/14.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:1:en","title":"Bhagavad Gita 14.1","text":"परं भूयः प्रवक्ष्यामि ज्ञानानां ज्ञानमुत्तमम् ।\nयज्ज्ञात्वा मुनयः सर्वे परां सिद्धिमितो गताः ॥","lang":"sa","roman":"paraṃ bhūyaḥ pravakṣyāmi jñānānāṃ jñānamuttamam |\nyajjñātvā munayaḥ sarve parāṃ siddhimito gatāḥ ||","body":"The Blessed Lord said: I will again proclaim that supreme Wisdom, of all wisdom the best, which having known, all the Sages have gone hence to the supreme Perfection.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","1 of 27"]]},"g2-14-1":{"route":"#/gitav/14.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:1:en2","title":"Gita 14.1, in another translation","body":"Again shall I tell thee that supreme knowledge which is above all knowledge, having known which all the Munis have attained to high perfection after this life.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","1 of 27"]]},"gv-14-2":{"route":"#/gitav/14.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:2:en","title":"Bhagavad Gita 14.2","text":"इदं ज्ञानमुपाश्रित्य मम साधर्म्यमागताः ।\nसर्गेऽपि नोपजायन्ते प्रलये न व्यथन्ति च ॥","lang":"sa","roman":"idaṃ jñānamupāśritya mama sādharmyamāgatāḥ |\nsarge’pi nopajāyante pralaye na vyathanti ca ||","body":"Having taken refuge in this Wisdom and being assimilated to My own nature, they are not re-born even in the emanation of a universe, nor are disquieted in the dissolution.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","2 of 27"]]},"g2-14-2":{"route":"#/gitav/14.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:2:en2","title":"Gita 14.2, in another translation","body":"They who having devoted themselves to this knowledge, have attained to My Being, are neither born at the time of creation, nor are they troubled at the time of dissolution.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","2 of 27"]]},"gv-14-3":{"route":"#/gitav/14.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:3:en","title":"Bhagavad Gita 14.3","text":"मम योनिर्महद्ब्रह्म तस्मिन् गर्भं दधाम्यहम् ।\nसंभवः सर्वभूतानां ततो भवति भारत ॥","lang":"sa","roman":"mama yonirmahadbrahma tasmin garbhaṃ dadhāmyaham |\nsaṃbhavaḥ sarvabhūtānāṃ tato bhavati bhārata ||","body":"My womb is the great Eternal; in that I place the germ; thence cometh the birth of all beings, O Bhârata.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","3 of 27"]]},"g2-14-3":{"route":"#/gitav/14.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:3:en2","title":"Gita 14.3, in another translation","body":"My womb is the great Prakriti; in that I place the germ; from thence, O descendant of Bharata, is the birth of all beings.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","3 of 27"]]},"gv-14-4":{"route":"#/gitav/14.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:4:en","title":"Bhagavad Gita 14.4","text":"सर्वयोनिषु कौन्तेय मूर्तयः सम्भवन्ति याः ।\nतासां ब्रह्म महद्योनिरहं बीजप्रदः पिता ॥","lang":"sa","roman":"sarvayoniṣu kaunteya mūrtayaḥ sambhavanti yāḥ |\ntāsāṃ brahma mahadyonirahaṃ bījapradaḥ pitā ||","body":"In whatsoever wombs mortals are produced, O Kaunteya, the great Eternal is their womb, I their generating father.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","4 of 27"]]},"g2-14-4":{"route":"#/gitav/14.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:4:en2","title":"Gita 14.4, in another translation","body":"Whatever forms are produced, O son of Kunti, in all the wombs, the great Prakriti is their womb, and I the seed-giving Father.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","4 of 27"]]},"gv-14-5":{"route":"#/gitav/14.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:5:en","title":"Bhagavad Gita 14.5","text":"सत्त्वं रजस्तम इति गुणाः प्रकृतिसंभवाः ।\nनिबध्नन्ति महाबाहो देहे देहिनमव्ययम् ॥","lang":"sa","roman":"sattvaṃ rajastama iti guṇāḥ prakṛtisaṃbhavāḥ |\nnibadhnanti mahābāho dehe dehinamavyayam ||","body":"Harmony, Motion, Inertia, such are the qualities, Matter-born; they bind fast in the body, O great-armed one, the indestructible dweller in the body.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","5 of 27"]]},"g2-14-5":{"route":"#/gitav/14.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:5:en2","title":"Gita 14.5, in another translation","body":"Sattva, Rajas, and Tamas,—these Gunas, O mighty-armed, born of Prakriti, bind fast in the body the indestructible embodied one.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","5 of 27"]]},"gv-14-6":{"route":"#/gitav/14.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:6:en","title":"Bhagavad Gita 14.6","text":"तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम् ।\nसुखसङ्गेन बध्नाति ज्ञानसङ्गेन चानघ ॥","lang":"sa","roman":"tatra sattvaṃ nirmalatvātprakāśakamanāmayam |\nsukhasaṅgena badhnāti jñānasaṅgena cānagha ||","body":"Of these Harmony from its stainlessness, luminous and healthy, bindeth by the attachment to bliss and the attachment to wisdom, O sinless one.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","6 of 27"]]},"g2-14-6":{"route":"#/gitav/14.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:6:en2","title":"Gita 14.6, in another translation","body":"Of these Sattva, from its stainlessness luminous and free from evil, binds, O sinless one, by attachment to happiness, and by attachment to knowledge.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","6 of 27"]]},"gv-14-7":{"route":"#/gitav/14.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:7:en","title":"Bhagavad Gita 14.7","text":"रजो रागात्मकं विद्धि तृष्णासङ्गसमुद्भवम् ।\nतन्निबध्नाति कौन्तेय कर्मसङ्गेन देहिनम् ॥","lang":"sa","roman":"rajo rāgātmakaṃ viddhi tṛṣṇāsaṅgasamudbhavam |\ntannibadhnāti kaunteya karmasaṅgena dehinam ||","body":"Motion, the passion nature, know thou, is the source of attachment and thirst for life, O Kaunteya, that bindeth the dweller in the body by the attachment to action.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","7 of 27"]]},"g2-14-7":{"route":"#/gitav/14.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:7:en2","title":"Gita 14.7, in another translation","body":"Know Rajas to be of the nature of passion, giving rise to thirst and attachment; it binds fast, O son of Kunti, the embodied one, by attachment to action.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","7 of 27"]]},"gv-14-8":{"route":"#/gitav/14.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:8:en","title":"Bhagavad Gita 14.8","text":"तमस्त्वज्ञानजं विद्धि मोहनं सर्वदेहिनाम् ।\nप्रमादालस्यनिद्राभिस्तन्निबध्नाति भारत ॥","lang":"sa","roman":"tamastvajñānajaṃ viddhi mohanaṃ sarvadehinām |\npramādālasyanidrābhistannibadhnāti bhārata ||","body":"But Inertia, know thou, born of unwisdom, is the deluder of all dwellers in the body; that bindeth by heedlessness, indolence and sloth, O Bharata.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","8 of 27"]]},"g2-14-8":{"route":"#/gitav/14.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:8:en2","title":"Gita 14.8, in another translation","body":"And know Tamas to be born of ignorance, stupefying all embodied beings; it binds fast, O descendant of Bharata, by miscomprehension, indolence, and sleep.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","8 of 27"]]},"gv-14-9":{"route":"#/gitav/14.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:9:en","title":"Bhagavad Gita 14.9","text":"सत्त्वं सुखे सञ्जयति रजः कर्मणि भारत ।\nज्ञानमावृत्य तु तमः प्रमादे सञ्जयत्युत ॥","lang":"sa","roman":"sattvaṃ sukhe sañjayati rajaḥ karmaṇi bhārata |\njñānamāvṛtya tu tamaḥ pramāde sañjayatyuta ||","body":"Harmony attacheth to bliss, Motion to action O Bharata. Inertia, verily, having shrouded wisdom, attacheth on the contrary to heedlessness.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","9 of 27"]]},"g2-14-9":{"route":"#/gitav/14.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:9:en2","title":"Gita 14.9, in another translation","body":"Sattva attaches to happiness, and Rajas to action, O descendant of Bharata; while Tamas, verily, shrouding discrimination, attaches to miscomprehension.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","9 of 27"]]},"gv-14-10":{"route":"#/gitav/14.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:10:en","title":"Bhagavad Gita 14.10","text":"रजस्तमश्चाभिभूय सत्त्वं भवति भारत ।\nरजः सत्त्वं तमश्चैव तमः सत्त्वं रजस्तथा ॥","lang":"sa","roman":"rajastamaścābhibhūya sattvaṃ bhavati bhārata |\nrajaḥ sattvaṃ tamaścaiva tamaḥ sattvaṃ rajastathā ||","body":"Now Harmony prevaileth, having overpowered Motion and Inertia, O Bhârata; now Motion, having overpowered Harmony and Inertia; and now Inertia, having overpowered Harmony and Motion.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","10 of 27"]]},"g2-14-10":{"route":"#/gitav/14.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:10:en2","title":"Gita 14.10, in another translation","body":"Sattva arises, O descendant of Bharata, predominating over Rajas and 'Tamas; and Rajas over Sattva and Tamas; so, Tamas over Sattva and Rajas.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","10 of 27"]]},"gv-14-11":{"route":"#/gitav/14.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:11:en","title":"Bhagavad Gita 14.11","text":"सर्वद्वारेषु देहेऽस्मिन्प्रकाश उपजायते ।\nज्ञानं यदा तदा विद्याद्विवृद्धं सत्त्वमित्युत ॥","lang":"sa","roman":"sarvadvāreṣu dehe’sminprakāśa upajāyate |\njñānaṃ yadā tadā vidyādvivṛddhaṃ sattvamityuta ||","body":"When the wisdom-light streameth forth from all the gates of the body, then it may be known that Harmony is increasing.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","11 of 27"]]},"g2-14-11":{"route":"#/gitav/14.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:11:en2","title":"Gita 14.11, in another translation","body":"When through every sense in this body, the light of intelligence shines, then it should be known that Sattva is predominant.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","11 of 27"]]},"gv-14-12":{"route":"#/gitav/14.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:12:en","title":"Bhagavad Gita 14.12","text":"लोभः प्रवृत्तिरारम्भः कर्मणामशमः स्पृहा ।\nरजस्येतानि जायन्ते विवृद्धे भरतर्षभ ॥","lang":"sa","roman":"lobhaḥ pravṛttirārambhaḥ karmaṇāmaśamaḥ spṛhā |\nrajasyetāni jāyante vivṛddhe bharatarṣabha ||","body":"Greed, outgoing energy, undertaking of actions, restlessness, desire—these are born of the increase of Motion, O best of the Bhâratas.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","12 of 27"]]},"g2-14-12":{"route":"#/gitav/14.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:12:en2","title":"Gita 14.12, in another translation","body":"Greed, activity, the undertaking of actions, unrest, longing—these arise when Rajas is predominant, O bull of the: Bhâratas.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","12 of 27"]]},"gv-14-13":{"route":"#/gitav/14.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:13:en","title":"Bhagavad Gita 14.13","text":"अप्रकाशोऽप्रवृत्तिश्च प्रमादो मोह एव च ।\nतमस्येतानि जायन्ते विवृद्धे कुरुनन्दन ॥","lang":"sa","roman":"aprakāśo’pravṛttiśca pramādo moha eva ca |\ntamasyetāni jāyante vivṛddhe kurunandana ||","body":"Darkness, stagnation and heedlessness and also delusion—these are born of the increase of Inertia, O joy of the Kurus.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","13 of 27"]]},"g2-14-13":{"route":"#/gitav/14.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:13:en2","title":"Gita 14.13, in another translation","body":"Darkness, inertness, miscomprehension, and delusion,—these arise when Tamas is predominant, O descendant of Kuru.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","13 of 27"]]},"gv-14-14":{"route":"#/gitav/14.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:14:en","title":"Bhagavad Gita 14.14","text":"यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत् ।\nतदोत्तमविदां लोकानमलान्प्रतिपद्यते ॥","lang":"sa","roman":"yadā sattve pravṛddhe tu pralayaṃ yāti dehabhṛt |\ntadottamavidāṃ lokānamalānpratipadyate ||","body":"If Harmony verily prevaileth when the embodied goeth to dissolution, then he goeth forth to the spotless worlds of the great Sages.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","14 of 27"]]},"g2-14-14":{"route":"#/gitav/14.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:14:en2","title":"Gita 14.14, in another translation","body":"If the embodied one meets death when Sattva is predominant, then he attains to the spotless regions of the worshippers of the Highest.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","14 of 27"]]},"gv-14-15":{"route":"#/gitav/14.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:15:en","title":"Bhagavad Gita 14.15","text":"रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते ।\nतथा प्रलीनस्तमसि मूढयोनिषु जायते ॥","lang":"sa","roman":"rajasi pralayaṃ gatvā karmasaṅgiṣu jāyate |\ntathā pralīnastamasi mūḍhayoniṣu jāyate ||","body":"Having gone to dissolution in Motion, he is born among those attached to action; if dissolved in Inertia, he is born in the wombs of the senseless.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","15 of 27"]]},"g2-14-15":{"route":"#/gitav/14.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:15:en2","title":"Gita 14.15, in another translation","body":"Meeting death in Rajas he is born among those attached to action; so dying in Tamas, he is born in the wombs of the irrational.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","15 of 27"]]},"gv-14-16":{"route":"#/gitav/14.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:16:en","title":"Bhagavad Gita 14.16","text":"कर्मणः सुकृतस्याहुः सात्त्विकं निर्मलं फलम् ।\nरजसस्तु फलं दुःखमज्ञानं तमसः फलम् ॥","lang":"sa","roman":"karmaṇaḥ sukṛtasyāhuḥ sāttvikaṃ nirmalaṃ phalam |\nrajasastu phalaṃ duḥkhamajñānaṃ tamasaḥ phalam ||","body":"It is said the fruit of a good action is harmonious and spotless; verily the fruit of Motion is pain, and the fruit of Inertia unwisdom","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","16 of 27"]]},"g2-14-16":{"route":"#/gitav/14.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:16:en2","title":"Gita 14.16, in another translation","body":"The fruit of good action, they say, is Sâttvika and pure; verily, the fruit of Rajas is pain, and ignorance is the fruit of Tamas.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","16 of 27"]]},"gv-14-17":{"route":"#/gitav/14.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:17:en","title":"Bhagavad Gita 14.17","text":"सत्त्वात्सञ्जायते ज्ञानं रजसो लोभ एव च ।\nप्रमादमोहौ तमसो भवतोऽज्ञानमेव च ॥","lang":"sa","roman":"sattvātsañjāyate jñānaṃ rajaso lobha eva ca |\npramādamohau tamaso bhavato’jñānameva ca ||","body":"From Harmony wisdom is born, and also greed from Motion; heedlessness and delusion are of Inertia and also unwisdom.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","17 of 27"]]},"g2-14-17":{"route":"#/gitav/14.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:17:en2","title":"Gita 14.17, in another translation","body":"From Sattva arises wisdom, and greed from Rajas; miscomprehension, delusion and ignorance arise from Tamas.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","17 of 27"]]},"gv-14-18":{"route":"#/gitav/14.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:18:en","title":"Bhagavad Gita 14.18","text":"ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः ।\nजघन्यगुणवृत्तिस्था अधो गच्छन्ति तामसाः ॥","lang":"sa","roman":"ūrdhvaṃ gacchanti sattvasthā madhye tiṣṭhanti rājasāḥ |\njaghanyaguṇavṛttisthā adho gacchanti tāmasāḥ ||","body":"They rise upwards who are settled in Harmony; the Active dwell in the mid-most place: the Inert go downwards, enveloped in the vilest","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","18 of 27"]]},"g2-14-18":{"route":"#/gitav/14.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:18:en2","title":"Gita 14.18, in another translation","body":"The Sattva-abiding go upwards; the Râjasika dwell in the middle; and the Tâmasika, abiding in the function. of the lowest Guna, go downwards.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","18 of 27"]]},"gv-14-19":{"route":"#/gitav/14.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:19:en","title":"Bhagavad Gita 14.19","text":"नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति ।\nगुणेभ्यश्च परं वेत्ति मद्भावं सोऽधिगच्छति ॥","lang":"sa","roman":"nānyaṃ guṇebhyaḥ kartāraṃ yadā draṣṭānupaśyati |\nguṇebhyaśca paraṃ vetti madbhāvaṃ so’dhigacchati ||","body":"When the Seer perceiveth no agent other than the qualities, and knoweth That which is higher than the qualities, he entereth into My Nature.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","19 of 27"]]},"g2-14-19":{"route":"#/gitav/14.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:19:en2","title":"Gita 14.19, in another translation","body":"When the seer beholds no agent other than the Gunas and knows That which is higher than the Gunas, he attains to My being.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","19 of 27"]]},"gv-14-20":{"route":"#/gitav/14.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:20:en","title":"Bhagavad Gita 14.20","text":"गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान् ।\nजन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते ॥","lang":"sa","roman":"guṇānetānatītya trīndehī dehasamudbhavān |\njanmamṛtyujarāduḥkhairvimukto’mṛtamaśnute ||","body":"When the dweller in the body hath crossed over these three qualities, whence all bodies have been produced, liberated from birth, death, old age and sorrow, he drinketh the nectar of immortality.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","20 of 27"]]},"g2-14-20":{"route":"#/gitav/14.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:20:en2","title":"Gita 14.20, in another translation","body":"The embodied one having gone beyond these three Gunas out of which the body is evolved, is freed from birth, death, decay and pain, and attains to immortality.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","20 of 27"]]},"gv-14-21":{"route":"#/gitav/14.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:21:en","title":"Bhagavad Gita 14.21","text":"कैर्लिंगैस्त्रीन्गुणानेतानतीतो भवति प्रभो ।\nकिमाचारः कथं चैतांस्त्रीन्गुणानतिवर्तते ॥","lang":"sa","roman":"kairliṃgaistrīnguṇānetānatīto bhavati prabho |\nkimācāraḥ kathaṃ caitāṃstrīnguṇānativartate ||","body":"Arjuna said: What are the marks of him who hath crossed over the three qualities, O Lord? How acteth he, and how doth he go beyond these three qualities?","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","21 of 27"]]},"g2-14-21":{"route":"#/gitav/14.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:21:en2","title":"Gita 14.21, in another translation","body":"By what marks, O Lord, is he (known) who has gone beyond these three Gunas? What is his conduct, and how does he pass beyond these three Gunas?","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","21 of 27"]]},"gv-14-22":{"route":"#/gitav/14.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:22:en","title":"Bhagavad Gita 14.22","text":"प्रकाशं च प्रवृत्तिं च मोहमेव च पाण्डव ।\nन द्वेष्टि सम्प्रवृत्तानि न निवृत्तानि काङ्क्षति ॥","lang":"sa","roman":"prakāśaṃ ca pravṛttiṃ ca mohameva ca pāṇḍava |\nna dveṣṭi sampravṛttāni na nivṛttāni kāṅkṣati ||","body":"The Blessed Lord said: He, O Pândava, who hateth not radiance, nor outgoing energy, nor even delusion, when present, nor longeth after them, absent;","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","22 of 27"]]},"g2-14-22":{"route":"#/gitav/14.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:22:en2","title":"Gita 14.22, in another translation","body":"He who hates not the appearance of light, (the effect of Sattva), activity (the effect of Rajas), and delusion (the effect of Tamas), (in his own mind), O Pândava, nor longs for them when absent;","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","22 of 27"]]},"gv-14-23":{"route":"#/gitav/14.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:23:en","title":"Bhagavad Gita 14.23","text":"उदासीनवदासीनो गुणैर्यो न विचाल्यते ।\nगुणा वर्तन्त इत्येव योऽवतिष्ठति नेङ्गते ॥","lang":"sa","roman":"udāsīnavadāsīno guṇairyo na vicālyate |\nguṇā vartanta ityeva yo’vatiṣṭhati neṅgate ||","body":"He who, seated as a neutral, is unshaken by the qualities; who, saying, \"The qualities revolve,\" standeth apart immovable.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","23 of 27"]]},"g2-14-23":{"route":"#/gitav/14.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:23:en2","title":"Gita 14.23, in another translation","body":"He who, sitting like one unconcerned, is moved not by the Gunas, who, knowing that the Gunas operate, is Self-centred and swerves not;","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","23 of 27"]]},"gv-14-24":{"route":"#/gitav/14.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:24:en","title":"Bhagavad Gita 14.24","text":"समदुःखसुखः स्वस्थः समलोष्टाश्मकाञ्चनः ।\nतुल्यप्रियाप्रियो धीरस्तुल्यनिन्दात्मसंस्तुतिः ॥","lang":"sa","roman":"samaduḥkhasukhaḥ svasthaḥ samaloṣṭāśmakāñcanaḥ |\ntulyapriyāpriyo dhīrastulyanindātmasaṃstutiḥ ||","body":"Balanced in pleasure and pain, self-reliant, to whom a lump of earth, a rock and gold are alike, the same to loved and unloved, firm, the same in censure and in praise,","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","24 of 27"]]},"g2-14-24":{"route":"#/gitav/14.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:24:en2","title":"Gita 14.24, in another translation","body":"Alike in pleasure and pain, Self-abiding, regarding a clod of earth, a stone and gold alike; the same to agreeable and disagreeable, firm, the same in censure and, praise;","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","24 of 27"]]},"gv-14-25":{"route":"#/gitav/14.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:25:en","title":"Bhagavad Gita 14.25","text":"मानापमानयोस्तुल्यस्तुल्यो मित्रारिपक्षयोः ।\nसर्वारम्भपरित्यागी गुणातीतः स उच्यते ॥","lang":"sa","roman":"mānāpamānayostulyastulyo mitrāripakṣayoḥ |\nsarvārambhaparityāgī guṇātītaḥ sa ucyate ||","body":"The same in honour and ignominy, the same to friend and foe, abandoning all undertakings—he is said to have crossed over the qualities.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","25 of 27"]]},"g2-14-25":{"route":"#/gitav/14.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:25:en2","title":"Gita 14.25, in another translation","body":"The same in honour and disgrace, the same to friend and foe, relinquishing all undertakings—he is said to have gone beyond the Gunas.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","25 of 27"]]}});
